  const catLabel = (MOCK_CATS.find(c=>c.id===catId)||{}).label || 'Mock';
  titleEl.innerHTML = entry ? `<span class="icoEdit" aria-hidden="true"></span> ${catLabel} Edit Karo` : `➕ Naya ${catLabel} Add Karo`;
