    english: entry ? (entry.english||'') : '', gk: entry ? (entry.gk||'') : '',
    score: entry ? (entry.score||'') : '',
    right: entry ? (entry.right||'') : '', wrong: entry ? (entry.wrong||'') : '', skip: entry ? (entry.skip||'') : '',
