// ===== Super Practice =====
// 660 pre-built, fully self-contained mock-test HTML files (each already has
// its own question rendering, bilingual EN/HI toggle, dark mode, math/table
// rendering baked in) bundled under superpractice/<subject>/mock_NNN.html.
// Rather than re-parsing all 660 files' questions into this app's own quiz
// engine (which would risk losing images/tables/bilingual toggles some of
// them use), each mock is shown as-is inside an iframe — subject menu ->
// mock list -> iframe player. superpractice/manifest.json (built once at
// packaging time) lists every mock's filename + question count per subject.
const SUPERPRACTICE_SUBJECTS = [
  { key:'math',      label:'Quant (Math)',            icon:'🧮', count:196 },
  { key:'reasoning', label:'Reasoning',                icon:'🧠', count:146 },
  { key:'english',   label:'English',                  icon:'📘', count:135 },
  { key:'gk',        label:'GK / General Awareness',   icon:'🌍', count:169 },
  { key:'computer',  label:'Computer Knowledge',        icon:'💻', count:14 },
];
let spManifest = null;
let spCurrentSubjectKey = null;
let spCurrentSubjectLabel = null;
let spCurrentEntries = [];

let spDirectEntry = false; // true when the list was opened from a Super Sets card (back -> Calc menu)

// ===== Super Sets: Super English / Maths / Reasoning, Optional Elimination and
// the Reading sets run on the SAME native Super Practice engine (instructions ->
// timed exam with palette -> result + solutions). Their question banks are plain
// JSON under data/, so each "mock" is a slice built on the fly (no extra files).
const SPV = {
  sreasoning:{ label:'Super Reasoning',               stats:'reasoning', perQ:0.9 },
  senglish:  { label:'Super English',                 stats:'english',   perQ:0.6 },
  smaths:    { label:'Super Maths',                   stats:'quant',     perQ:1.2 },
  optelim:   { label:'Optional Elimination',          stats:null,        perQ:0.6 },
  rd98:      { label:'PYQ Reading — 98 Sets',         stats:'english',   perQ:0.8 },
  rdtype:    { label:'PYQ Reading Practice',          stats:'english',   perQ:0.8 },
  rdnew:     { label:'NEW Reading — Advanced Sets',   stats:'english',   perQ:0.8 }
};
const SPV_CH = { sreasoning:'data/reasoning/', senglish:'data/superenglish/', smaths:'data/maths/' };
const spvCache = {};
function spvJ(url){
  if(spvCache[url]) return Promise.resolve(spvCache[url]);
  return fetch(url).then(r => { if(!r.ok) throw new Error(r.status); return r.json(); }).then(d => { spvCache[url] = d; return d; });
}
function spvFmt(s){
  const h = String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/&lt;(\/?)(b|u|i|sup|sub)&gt;/g,'<$1$2>')
    .replace(/&lt;img src="(https:\/\/[^"\s<>]+)"&gt;/g,'<img src="$1" style="max-width:100%;height:auto;vertical-align:middle">');
  return h.replace(/\n/g,'<br>');
}
function spvMk(qh, qhi, oen, ohi, ans, sol, solhi){
  return { q_en:qh, q_hi:qhi, options_en:oen, options_hi:ohi, answer:ans,
           solution_en:sol || '<p>Explanation available nahi.</p>', solution_hi:solhi || sol || '<p>Explanation available nahi.</p>',
           marks:1, neg:0.25 };
}
function spvBand(i, size, total){ // "Sets 001-010" style chapter bands (sorted as given)
  const a = Math.floor(i / size) * size + 1, b = Math.min(total, a + size - 1);
  const p = n => String(n).padStart(3,'0');
  return 'Sets ' + p(a) + '–' + p(b);
}
async function spvEntries(key){
  if(SPV_CH[key]){
    const idx = await spvJ(SPV_CH[key] + 'index.json');
    const out = []; let n = 0;
    idx.chapters.forEach(ch => {
      const sets = Math.ceil(ch.n / 10);
      for(let k = 0; k < sets; k++){
        n++;
        out.push({ n:n, q:Math.min(10, ch.n - k * 10), file:ch.key + '_' + (k + 1) + '.html', topic:(ch.icon ? ch.icon + ' ' : '') + ch.label,
                   label:'Set ' + (k + 1), ch:ch.key, from:k * 10, to:Math.min(ch.n, k * 10 + 10) });
      }
    });
    return out;
  }
  if(key === 'optelim'){
    const d = await spvJ('data/optelim/data.json');
    return d.S.map((lst, i) => ({ n:i + 1, q:lst.length, file:'set_' + (i + 1) + '.html', topic:spvBand(i, 10, d.S.length), label:'Set ' + (i + 1) + ' · ' + lst.length + ' Q', idx:lst }));
  }
  if(key === 'rd98' || key === 'rdnew' || key === 'rdtype'){
    const by = await spvReadingUnits(key === 'rdnew');
    const mk = (ids) => spvReadingQs(by, ids).length;
    if(key === 'rdtype'){
      const idx = await spvJ('data/reading/index.json');
      const names = { c:'PYQ Cloze Test', r:'PYQ Reading Comprehension', p:'PYQ PQRS · Para Jumbles' };
      const out = []; let n = 0;
      ['c','r','p'].forEach(g => idx.ten[g].forEach((ids, k) => {
        n++; out.push({ n:n, q:mk(ids), file:g + '_' + (k + 1) + '.html', topic:names[g], label:'PYQ Set ' + (k + 1), ids:ids });
      }));
      return out;
    }
    const src = key === 'rdnew' ? (await spvJ('data/reading/adv.json')) : (await spvJ('data/reading/index.json'));
    return src.sets.map((s, i) => {
      const ids = s.c.concat(s.r, s.p);
      const tag = ' · Cloze ' + s.c.length + ' · RC ' + s.r.length + ' · PQRS ' + s.p.length;
      return key === 'rdnew'
        ? { n:s.n, q:mk(ids), file:'set_' + s.n + '.html', topic:'NEW Advanced Sets (Hard)', label:'NEW Set ' + s.n + tag, ids:ids }
        : { n:s.n, q:mk(ids), file:'set_' + s.n + '.html', topic:spvBand(i, 10, src.sets.length), label:'PYQ Set ' + s.n + tag, ids:ids };
    });
  }
  return [];
}
async function spvReadingUnits(adv){
  const by = {};
  if(adv){ (await spvJ('data/reading/adv.json')).units.forEach(u => by[u.i] = u); return by; }
  const all = await Promise.all(['c','r','p'].map(k => spvJ('data/reading/' + k + '.json')));
  all.forEach(arr => arr.forEach(u => by[u.i] = u));
  return by;
}
function spvReadingQs(by, ids){
  const out = [];
  ids.forEach(id => {
    const u = by[id]; if(!u) return;
    const isPJ = /^x?p/.test(u.i);
    u.q.forEach(q => {
      let ans = q.a, opts = q.o, extra = '';
      if(q.raw){
        const m = /\(\s*([a-d])\s*\)/i.exec(q.al || '');
        if(!m) return;                      // no usable answer in the source -> skip
        ans = 'abcd'.indexOf(m[1].toLowerCase());
        extra = '<div style="font-size:12px;opacity:.75;margin:8px 0 4px">⚠️ Source PDF mein options garbled hain — neeche jaise hain waise:</div>' +
          (q.o || []).map(o => '<div style="font-size:13px;opacity:.9;border:1px dashed rgba(127,127,127,.5);border-radius:8px;padding:6px 8px;margin-bottom:6px;max-height:160px;overflow:auto">' + spvFmt(o) + '</div>').join('');
        opts = ['(a)','(b)','(c)','(d)'];
      }
      if(!(ans >= 0 && ans < opts.length)) return;
      const lines = isPJ ? (q.pp || []) : (u.p || []);
      let h = '';
      if(q.sr) h += '<div style="font-size:11px;opacity:.65;margin-bottom:6px">' + spvFmt(q.sr) + '</div>';
      if(lines.length) h += '<div style="background:rgba(127,127,127,.12);border-left:3px solid #f59e0b;border-radius:8px;padding:10px 12px;margin-bottom:10px;line-height:1.6;font-size:15px">' +
        lines.map(l => '<p style="margin:0 0 6px">' + spvFmt(l) + '</p>').join('') + '</div>';
      (q.t || []).forEach(t => { h += '<p>' + spvFmt(t) + '</p>'; });
      h += extra;
      const sol = (q.e || q.raw) ? '<p>' + spvFmt((q.raw && q.al ? q.al + '\n\n' : '') + (q.e || '')) + '</p>' : '';
      out.push(spvMk(h, h, opts.map(spvFmt), opts.map(spvFmt), ans, sol));
    });
  });
  return out;
}
function spvSplitBi(o){
  const i = String(o).lastIndexOf(' / ');
  if(i > 0 && /[\u0900-\u097F]/.test(o.slice(i + 3))) return [o.slice(0, i), o.slice(i + 3)];
  return [o, o];
}
async function spvLoad(key, e){
  let qs;
  if(SPV_CH[key]){
    const arr = await spvJ(SPV_CH[key] + e.ch + '.json');
    qs = arr.slice(e.from, e.to).map(q => {
      const t = '<p>' + spvFmt(q.t) + '</p>', s = q.e ? '<p>' + spvFmt(q.e) + '</p>' : '';
      // Hindi (h / oh / eh) data/maths aur data/reasoning mein hai — na ho to English hi dikhao
      const th = q.h ? '<p>' + spvFmt(q.h) + '</p>' : t, sh = q.eh ? '<p>' + spvFmt(q.eh) + '</p>' : s;
      return spvMk(t, th, q.o.map(spvFmt), q.o.map((o, j) => spvFmt(q.oh && q.oh[j] != null ? q.oh[j] : o)), q.a, s, sh);
    });
  }else if(key === 'optelim'){
    const d = await spvJ('data/optelim/data.json');
    qs = e.idx.map(i => {
      const q = d.Q[i];
      const src = q.src ? '<div style="font-size:11px;opacity:.65;margin-top:6px">' + spvFmt(q.src) + '</div>' : '';
      const en = '<p>' + spvFmt(q.q[0]) + '</p>' + src, hi = '<p>' + spvFmt(q.q[1] || q.q[0]) + '</p>' + src;
      const bi = q.o.map(spvSplitBi);
      const sol = (q.t || []).map(x => '<p><b>' + spvFmt(d.T[x[0]] || 'Trick') + '</b><br>' + spvFmt(x[1]) + '</p>').join('');
      return spvMk(en, hi, bi.map(x => spvFmt(x[0])), bi.map(x => spvFmt(x[1])), q.a, sol);
    });
  }else{
    const by = await spvReadingUnits(key === 'rdnew');
    qs = spvReadingQs(by, e.ids);
  }
  return { title:SPV[key].label + ' — ' + e.label, duration_min:Math.max(5, Math.ceil(qs.length * SPV[key].perQ)), questions:qs };
}

async function ensureSPManifest(){
  if(spManifest) return spManifest;
  try{
    const res = await fetch('superpractice/manifest.json');
    spManifest = await res.json();
  }catch(e){ spManifest = {}; }
  return spManifest;
}

function renderSPSubjectGrid(){
  const grid = document.getElementById('superpracticeSubjectGrid');
  if(!grid) return;
  grid.innerHTML = '';
  // "Math Sectional" — jumps straight into the existing Math Mock exam
  // engine's mocks view (15-min, 25-Q, mixed-chapter tests), with its own
  // Concept Mock / 75-Day Practice toggle inside. Kept separate from the
  // iframe-based Quant (Math) card below since it's a different engine
  // (native exam UI, not pre-built HTML mocks).
  const mathSecBtn = document.createElement('button');
  mathSecBtn.className = 'calcCard calcCard-statement';
  mathSecBtn.innerHTML =
    '<span class="calcIcon calcIcon-statement">🔢</span>' +
    '<span class="calcLabelCol">' +
      '<span class="calcLabel">Math Sectional</span>' +
      '<span class="calcSub">15-min · 25 Qs mixed · Concept + 75-Day Practice</span>' +
    '</span>' +
    '<span class="calcArrow">&#8250;</span>';
  mathSecBtn.addEventListener('click', () => mathPyqQuiz.openMocksView('concept'));
  grid.appendChild(mathSecBtn);

  SUPERPRACTICE_SUBJECTS.forEach(s => {
    const btn = document.createElement('button');
    btn.className = 'calcCard calcCard-statement';
    btn.innerHTML =
      '<span class="calcIcon calcIcon-statement">' + s.icon + '</span>' +
      '<span class="calcLabelCol">' +
        '<span class="calcLabel">' + escapeHtml(s.label) + '</span>' +
        '<span class="calcSub">' + s.count + ' mocks</span>' +
      '</span>' +
      '<span class="calcArrow">&#8250;</span>';
    btn.addEventListener('click', () => openSPSubject(s.key, s.label));
    grid.appendChild(btn);
  });
}

async function openSPSubject(key, label, direct){
  spDirectEntry = direct || false;
  spCurrentSubjectKey = key;
  const titleEl = document.getElementById('superpracticeListTitle');
  if(titleEl) titleEl.textContent = '🔥 ' + label + ' — Choose a Mock';
  showCalcPage('superpracticelist');
  const grid = document.getElementById('superpracticeListGrid');
  if(grid) grid.innerHTML = '<div class="losshint">Loading mocks…</div>';
  const manifest = await ensureSPManifest();
  let entries = [];
  if(SPV[key]){ try{ entries = await spvEntries(key); }catch(err){ entries = []; } }
  else entries = (manifest && manifest[key]) || [];
  spCurrentSubjectLabel = label;
  spCurrentEntries = entries;
  const searchBox = document.getElementById('superpracticeSearchInput');
  if(searchBox) searchBox.value = '';
  spOpenChapter = null;
  spOpenGKSubject = null;
  spOpenGKSubtopic = null;
  renderSPMockGrid(entries);
}

// Groups a subject's mocks by their "topic" field into Oliveboard-style
// chapters — e.g. all "Percentage" mocks become one "Percentage" chapter
// with Level 1, Level 2... inside it, instead of a flat "Mixed Practice #1,
// #2, #3..." list. Untagged/mixed mocks are bucketed into a single "Mixed
// Practice" chapter and pushed to the bottom.
// Canonical Oliveboard SSC Quant curriculum order (matches the official
// "SSC Super Practice Tests" chapter sequence shown in the Oliveboard app).
// Used to sort the 'math' subject's chapters the same way Oliveboard does,
// instead of A-Z. Chapters not in this list fall back to the end, sorted
// alphabetically among themselves.
const OLIVEBOARD_MATH_CHAPTER_ORDER = [
  "Basics of Number System","Decimals and Fractions","Factors, Multiples and HCF/LCM",
  "Divisibility","Remainder Theorem","Unit Digits and finding number of zeroes",
  "Simplification","Surds","Indices","Percentages","Ratio and Proportion",
  "Averages and Ages","Profit, Loss, and Discount","Profit and Loss: Dishonest seller",
  "Partnerships","Mixtures and Alligations","Simple Interest","Compound Interest",
  "Simple and Compound Interest: Installments","Time and Work",
  "Time and Work: Pipes and Cisterns","Speed, Distance and Time","Trains",
  "Boats and Streams","Races and Tracks","Circular Motion in Speed, Time and Distance",
  "Polynomials and Linear Equations","Algebra One Variable","Algebra Two Variables",
  "Algebra Three Variables","Quadratic Equations","Trigonometric Ratios",
  "Trigonometric Identities","Heights and Distances","Lines and Angles","Triangles",
  "Quadrilaterals & Polygons","Circles","Coordinate Geometry","2D Mensuration 1",
  "2D Mensuration 2","3D Mensuration 1","3D Mensuration 2","3D Mensuration 3",
  "3D Mensuration 4","DI Tables","DI Bar, Line graphs and Histogram","DI Pie Charts",
  "DI Double Graphs","Series and Progressions","Set Theory",
  "Permutation and Combination","Probability","Statistics","Quant","Base Conversion"
];
// Canonical order for the levels/types shown inside an opened chapter.
const OLIVEBOARD_MATH_LABEL_ORDER = [
  "Level 1","Level 2","Level 3","Past Year Questions","Most Repetitive Questions",
  "Speed Improvement","Revision"
];

// Canonical order for the 'quant' subject (21 broader buckets — different
// granularity than 'math'). Sectional Mock and Mixed Practice always last,
// matching how Oliveboard's own quant list ends.
const OLIVEBOARD_QUANT_CHAPTER_ORDER = [
  "Number System","HCF & LCM","Simplification","Percentage","Ratio & Proportion",
  "Average","Profit & Loss","Mixture & Alligation","Simple & Compound Interest",
  "Time & Work","Pipes & Cisterns","Time, Speed & Distance","Algebra","Trigonometry",
  "Height & Distance","Mensuration (2D)","Mensuration (3D)","Statistics","Probability",
  "Sectional Mock","Mixed Practice"
];

// GK 'topic' strings are "Subject: Subtopic" (e.g. "Ancient History: Mauryan
// Empire"). This canonical order controls which Subject button appears
// first — subtopics within a subject are just sorted alphabetically.
const GK_SUBJECT_ORDER = [
  "Ancient History","Medieval History","Modern History","Polity","Economy",
  "Geography","Physics","Chemistry","Biology","Art and Culture","Static GK",
  "Census, Reports and Schemes"
];
function parseGKTopic(topic){
  const t = (topic || '').trim();
  const idx = t.indexOf(':');
  if(idx === -1) return { subject: 'Other', subtopic: t || 'Mixed Practice' };
  return { subject: t.slice(0, idx).trim(), subtopic: t.slice(idx + 1).trim() };
}
// Two-level version of groupSPEntries, used only for the 'gk' subject:
// Subject -> [ { subtopic, items } ], subjects and subtopics each sorted.
function groupGKEntries(entries){
  const bySubject = new Map();
  entries.forEach(e => {
    const { subject, subtopic } = parseGKTopic(e.topic);
    if(!bySubject.has(subject)) bySubject.set(subject, new Map());
    const bySub = bySubject.get(subject);
    if(!bySub.has(subtopic)) bySub.set(subtopic, []);
    bySub.get(subtopic).push(e);
  });
  const subjects = Array.from(bySubject.entries()).map(([subject, subMap]) => {
    const subtopics = Array.from(subMap.entries()).map(([subtopic, items]) => ({ subtopic, items }));
    subtopics.sort((a, b) => a.subtopic.localeCompare(b.subtopic));
    const count = subtopics.reduce((s, x) => s + x.items.length, 0);
    return { subject, subtopics, count };
  });
  subjects.sort((a, b) => {
    const ai = GK_SUBJECT_ORDER.indexOf(a.subject);
    const bi = GK_SUBJECT_ORDER.indexOf(b.subject);
    if(ai === -1 && bi === -1) return a.subject.localeCompare(b.subject);
    if(ai === -1) return 1;
    if(bi === -1) return -1;
    return ai - bi;
  });
  return subjects;
}

function groupSPEntries(entries){
  const map = new Map();
  entries.forEach(e => {
    const key = (e.topic || 'Mixed Practice').trim();
    if(!map.has(key)) map.set(key, []);
    map.get(key).push(e);
  });
  const chapters = Array.from(map.entries()).map(([topic, items]) => ({ topic, items }));
  if(SPV[spCurrentSubjectKey]){
    /* Super Sets: chapters/sets stay in the order they were built */
  } else if(spCurrentSubjectKey === 'math'){
    chapters.forEach(ch => {
      ch.items.sort((a, b) => {
        const ai = OLIVEBOARD_MATH_LABEL_ORDER.indexOf((a.label || '').trim());
        const bi = OLIVEBOARD_MATH_LABEL_ORDER.indexOf((b.label || '').trim());
        return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
      });
    });
    chapters.sort((a, b) => {
      const ai = OLIVEBOARD_MATH_CHAPTER_ORDER.indexOf(a.topic);
      const bi = OLIVEBOARD_MATH_CHAPTER_ORDER.indexOf(b.topic);
      if(ai === -1 && bi === -1) return a.topic.localeCompare(b.topic);
      if(ai === -1) return 1;
      if(bi === -1) return -1;
      return ai - bi;
    });
  } else if(spCurrentSubjectKey === 'quant'){
    chapters.sort((a, b) => {
      const ai = OLIVEBOARD_QUANT_CHAPTER_ORDER.indexOf(a.topic);
      const bi = OLIVEBOARD_QUANT_CHAPTER_ORDER.indexOf(b.topic);
      if(ai === -1 && bi === -1) return a.topic.localeCompare(b.topic);
      if(ai === -1) return 1;
      if(bi === -1) return -1;
      return ai - bi;
    });
  } else {
    chapters.sort((a, b) => {
      if(a.topic === 'Mixed Practice' && b.topic !== 'Mixed Practice') return 1;
      if(b.topic === 'Mixed Practice' && a.topic !== 'Mixed Practice') return -1;
      return a.topic.localeCompare(b.topic);
    });
  }
  return chapters;
}

let spOpenChapter = null; // currently expanded chapter name, or null
let spOpenGKSubject = null;  // currently expanded GK subject, or null
let spOpenGKSubtopic = null; // currently expanded GK subtopic, or null

function renderSPMockRows(items, body){
  items.forEach((e, idx) => {
    const done = isQuizSetAttempted('spnative', spCurrentSubjectKey + '/' + e.file);
    const rowLabel = (e.label || e.topic || ('Level ' + (idx + 1)));
    const row = document.createElement('button');
    row.style.cssText = 'width:100%;display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:transparent;border:none;border-bottom:1px solid var(--border);text-align:left;cursor:pointer;font-size:14px;color:inherit;';
    row.innerHTML =
      '<span>' + escapeHtml(rowLabel) + (done ? ' <span style="color:var(--gain,#16A34A);">✅</span>' : '') + '</span>' +
      '<span style="color:var(--muted);font-size:13px;">' + e.q + ' Qs &#8250;</span>';
    row.addEventListener('click', () => openSPMock(spCurrentSubjectKey, e.file, spCurrentSubjectLabel, e));
    body.appendChild(row);
  });
  const lastRow = body.lastElementChild;
  if(lastRow) lastRow.style.borderBottom = 'none';
}

function renderSPMockGridGK(entries){
  const grid = document.getElementById('superpracticeListGrid');
  if(!grid) return;
  grid.classList.remove('calcGrid', 'calcGrid-2col');
  grid.innerHTML = '';
  const subjects = groupGKEntries(entries);
  if(!subjects.length){
    grid.innerHTML = '<div class="losshint">Koi mock nahi mila.</div>';
    return;
  }
  subjects.forEach(subj => {
    const isSubjOpen = spOpenGKSubject === subj.subject;
    const wrap = document.createElement('div');
    wrap.style.cssText = 'border:1px solid var(--border);border-radius:12px;margin-bottom:10px;overflow:hidden;background:var(--panel);';

    const header = document.createElement('button');
    header.style.cssText = 'width:100%;display:flex;align-items:center;justify-content:space-between;padding:14px 16px;background:transparent;border:none;text-align:left;font-size:15px;font-weight:600;cursor:pointer;color:inherit;';
    header.innerHTML =
      '<span>' + escapeHtml(subj.subject) + '</span>' +
      '<span style="display:flex;align-items:center;gap:8px;font-weight:400;font-size:13px;color:var(--muted);">' +
        subj.count + ' mocks' +
        '<span style="display:inline-block;transform:rotate(' + (isSubjOpen ? 90 : 0) + 'deg);transition:transform .15s;">&#8250;</span>' +
      '</span>';
    header.addEventListener('click', () => {
      spOpenGKSubject = isSubjOpen ? null : subj.subject;
      spOpenGKSubtopic = null;
      renderSPMockGridGK(entries);
    });
    wrap.appendChild(header);

    if(isSubjOpen){
      const body = document.createElement('div');
      body.style.cssText = 'border-top:1px solid var(--border);';
      subj.subtopics.forEach(st => {
        const isSubOpen = spOpenGKSubtopic === st.subtopic;
        const subWrap = document.createElement('div');
        subWrap.style.cssText = 'border-bottom:1px solid var(--border);';

        const subHeader = document.createElement('button');
        subHeader.style.cssText = 'width:100%;display:flex;align-items:center;justify-content:space-between;padding:12px 16px 12px 24px;background:transparent;border:none;text-align:left;font-size:14px;font-weight:500;cursor:pointer;color:inherit;';
        subHeader.innerHTML =
          '<span>' + escapeHtml(st.subtopic) + '</span>' +
          '<span style="display:flex;align-items:center;gap:8px;font-weight:400;font-size:12px;color:var(--muted);">' +
            st.items.length + ' mocks' +
            '<span style="display:inline-block;transform:rotate(' + (isSubOpen ? 90 : 0) + 'deg);transition:transform .15s;">&#8250;</span>' +
          '</span>';
        subHeader.addEventListener('click', () => {
          spOpenGKSubtopic = isSubOpen ? null : st.subtopic;
          renderSPMockGridGK(entries);
        });
        subWrap.appendChild(subHeader);

        if(isSubOpen){
          const innerBody = document.createElement('div');
          innerBody.style.cssText = 'background:var(--bg,transparent);';
          renderSPMockRows(st.items, innerBody);
          subWrap.appendChild(innerBody);
        }
        body.appendChild(subWrap);
      });
      const lastSub = body.lastElementChild;
      if(lastSub) lastSub.style.borderBottom = 'none';
      wrap.appendChild(body);
    }

    grid.appendChild(wrap);
  });
}

function renderSPMockGrid(entries){
  if(spCurrentSubjectKey === 'gk'){ renderSPMockGridGK(entries); return; }
  const grid = document.getElementById('superpracticeListGrid');
  if(!grid) return;
  grid.classList.remove('calcGrid', 'calcGrid-2col');
  grid.innerHTML = '';
  const chapters = groupSPEntries(entries);
  if(!chapters.length){
    grid.innerHTML = '<div class="losshint">Koi mock nahi mila.</div>';
    return;
  }
  chapters.forEach(ch => {
    const isOpen = spOpenChapter === ch.topic;
    const wrap = document.createElement('div');
    wrap.style.cssText = 'border:1px solid var(--border);border-radius:12px;margin-bottom:10px;overflow:hidden;background:var(--panel);';

    const header = document.createElement('button');
    header.style.cssText = 'width:100%;display:flex;align-items:center;justify-content:space-between;padding:14px 16px;background:transparent;border:none;text-align:left;font-size:15px;font-weight:600;cursor:pointer;color:inherit;';
    header.innerHTML =
      '<span>' + escapeHtml(ch.topic) + '</span>' +
      '<span style="display:flex;align-items:center;gap:8px;font-weight:400;font-size:13px;color:var(--muted);">' +
        ch.items.length + ' mocks' +
        '<span style="display:inline-block;transform:rotate(' + (isOpen ? 90 : 0) + 'deg);transition:transform .15s;">&#8250;</span>' +
      '</span>';
    header.addEventListener('click', () => {
      spOpenChapter = isOpen ? null : ch.topic;
      renderSPMockGrid(entries);
    });
    wrap.appendChild(header);

    if(isOpen){
      const body = document.createElement('div');
      body.style.cssText = 'border-top:1px solid var(--border);';
      renderSPMockRows(ch.items, body);
      wrap.appendChild(body);
    }

    grid.appendChild(wrap);
  });
}

function filterSPMockGrid(query){
  const q = (query || '').trim().toLowerCase();
  if(!q){
    spOpenChapter = null; spOpenGKSubject = null; spOpenGKSubtopic = null;
    renderSPMockGrid(spCurrentEntries);
    return;
  }
  const filtered = spCurrentEntries.filter(e => (e.label || '').toLowerCase().includes(q) || (e.topic || '').toLowerCase().includes(q));
  if(spCurrentSubjectKey === 'gk'){
    const subjects = groupGKEntries(filtered);
    if(subjects.length === 1){
      spOpenGKSubject = subjects[0].subject;
      spOpenGKSubtopic = subjects[0].subtopics.length === 1 ? subjects[0].subtopics[0].subtopic : null;
    }
    renderSPMockGridGK(filtered);
    return;
  }
  const chapters = groupSPEntries(filtered);
  if(chapters.length === 1) spOpenChapter = chapters[0].topic;
  renderSPMockGrid(filtered);
}

// ===== Super Practice: native player =====
// Pre-converted data lives at superpractice/data/<key>/mock_NNN.json (see
// extract_sp.py), one JSON per original mock_NNN.html, schema:
//   { title, duration_min, questions: [ { q_en, q_hi, options_en, options_hi,
//     answer(0-based), solution_en, solution_hi, marks, neg } ] }
// Same Testbook-style exam UI as EM Mocks (instructions -> timed exam with
// palette/mark-for-review -> result+solution review), but with a live
// EN/हिंदी toggle since Super Practice source files carry both languages
// (unlike EM Mocks' already-English-only source).
function fixMockImageTags(html){
  if(!html || typeof html !== 'string' || html.indexOf('<img') === -1) return html;
  // Oliveboard-hosted question images (u1.oliveboard.in) block hotlinking when
  // the browser sends a Referer header from another origin (our github.io
  // site), which shows up as a broken image icon. Stripping the referrer via
  // referrerpolicy="no-referrer" makes the request look "direct" and the
  // image loads normally. Applied once right after a mock's JSON is fetched.
  return html.replace(/<img\s/gi, '<img referrerpolicy="no-referrer" loading="lazy" ');
}
function fixMockImagesInData(data){
  if(!data || !Array.isArray(data.questions)) return data;
  data.questions.forEach(q => {
    ['q_en','q_hi','solution_en','solution_hi'].forEach(k => {
      if(q[k]) q[k] = fixMockImageTags(q[k]);
    });
    ['options_en','options_hi'].forEach(k => {
      if(Array.isArray(q[k])) q[k] = q[k].map(o => fixMockImageTags(o));
    });
  });
  return data;
}
let spnativeLoaded = null;
let spnativeMockLabel = '';
// Mixed Practice (quant "sectional" mocks): behave like a real mock —
// 15 min fixed timer, answers only revealed after final Submit — instead
// of Super Practice's usual instant-reveal-per-question quiz style.
let spnativeMockModeActive = false;
let spnativeCurrentKey = null;
let spnativeCurrentFile = null;
let spnativeLang = 'en'; // 'en' | 'hi'
const spnativeSession = {
  questions: [], answers: [], marked: [], visited: [], locked: [],
  current: 0, timeLeft: 0, timerId: null, submitted: false, paused: false
};

function nativeHasHiContent(arr){ return Array.isArray(arr) && arr.some(s => (s || '').toString().trim().length > 0); }
function spnativeQText(q){ return spnativeLang === 'hi' && (q.q_hi || '').trim() ? q.q_hi : q.q_en; }
function spnativeOpts(q){ return spnativeLang === 'hi' && nativeHasHiContent(q.options_hi) ? q.options_hi : q.options_en; }
function spnativeSolText(q){ return spnativeLang === 'hi' && (q.solution_hi || '').trim() ? q.solution_hi : q.solution_en; }

function spnativeUpdateLangBtns(){
  const label = spnativeLang === 'hi' ? '🌐 हिं' : '🌐 EN';
  ['spnativeInfoLangBtn','spnativeExamLangBtn','spnativeResultLangBtn'].forEach(id => {
    const b = document.getElementById(id);
    if(b) b.textContent = label;
  });
}
function spnativeToggleLang(){
  spnativeLang = spnativeLang === 'hi' ? 'en' : 'hi';
  spnativeUpdateLangBtns();
  // Re-render whichever screen is currently visible with the new language
  const examPage = document.getElementById('calcPage-spnativeexam');
  const resultPage = document.getElementById('calcPage-spnativeresult');
  if(examPage && examPage.classList.contains('active')) spnativeRenderQuestion();
  else if(resultPage && resultPage.classList.contains('active')) spnativeResultRenderQuestion();
}

async function openSPMock(key, file, label, entry){
  spnativeCurrentKey = key;
  spnativeCurrentFile = file;
  const spExamPageEl = document.getElementById('calcPage-spnativeexam');
  if(spExamPageEl) spExamPageEl.dataset.subject = key;
  const spResultPageEl = document.getElementById('calcPage-spnativeresult');
  if(spResultPageEl) spResultPageEl.dataset.subject = key;
  spnativeMockModeActive = (key === 'quant' && entry && entry.topic === 'Mixed Practice');
  spnativeMockLabel = label + ' — ' + (entry.label || ('Mock ' + entry.n));
  const jsonFile = file.replace(/\.html$/, '.json');
  const infoTitleEl = document.getElementById('spnativeInfoTitle');
  if(infoTitleEl) infoTitleEl.textContent = spnativeMockLabel;
  spnativeUpdateLangBtns();
  showCalcPage('spnativeinfo');
  const qc = document.getElementById('spnativeInfoQCount'); if(qc) qc.textContent = '…';
  spnativeLoaded = null;
  const startBtn = document.getElementById('spnativeStartBtn');
  const startBtnOldLabel = startBtn ? startBtn.textContent : '';
  if(startBtn){ startBtn.disabled = true; startBtn.textContent = '⏳ Mock download ho raha hai...'; }
  let data;
  try{
    if(SPV[key]){ data = await spvLoad(key, entry); }
    else{ const res = await fetch('superpractice/data/' + key + '/' + jsonFile); data = await res.json(); }
    data = fixMockImagesInData(data);
  }catch(e){
    alert('Ye mock load nahi ho paaya. Dobara try karein.');
    showCalcPage('superpracticelist');
    return;
  }
  if(!data || !data.questions || !data.questions.length){
    alert('Ye mock abhi available nahi hai.');
    showCalcPage('superpracticelist');
    return;
  }
  spnativeLoaded = data;
  if(startBtn){ startBtn.disabled = false; startBtn.textContent = startBtnOldLabel || '▶ Start Test'; }
  const totalQ = data.questions.length;
  const totalMarks = data.questions.reduce((s, q) => s + (q.marks || 0), 0);
  const firstQ = data.questions[0] || { marks: 1, neg: 0.25 };
  if(qc) qc.textContent = totalQ;
  const tm = document.getElementById('spnativeInfoMarks');
  if(tm) tm.textContent = Math.round(totalMarks * 100) / 100;
  const du = document.getElementById('spnativeInfoDuration');
  if(du) du.textContent = (data.duration_min || 15) + ' minutes';
  const mk = document.getElementById('spnativeInfoMarking');
  if(mk) mk.textContent = '+' + firstQ.marks + ' / -' + firstQ.neg;
}

function spnativeFormatMarks(m){ return (Math.round(m * 100) / 100).toString(); }
function spnativeFormatTime(sec){
  const s = Math.max(0, sec);
  const m = Math.floor(s / 60);
  const r = s % 60;
  return (m < 10 ? '0' + m : m) + ':' + (r < 10 ? '0' + r : r);
}

function spnativeStartExam(){
  if(!spnativeLoaded) return;
  spnativeSession.questions = spnativeLoaded.questions;
  const n = spnativeSession.questions.length;
  spnativeSession.answers = new Array(n).fill(null);
  spnativeSession.marked = new Array(n).fill(false);
  spnativeSession.visited = new Array(n).fill(false);
  spnativeSession.locked = new Array(n).fill(false);
  spnativeSession.current = 0;
  spnativeSession.timeLeft = spnativeMockModeActive ? 15 * 60 : (spnativeLoaded.duration_min || 15) * 60;
  spnativeSession.submitted = false;
  spnativeSession.paused = false;
  const titleEl = document.getElementById('spnativeExamTitle');
  if(titleEl) titleEl.textContent = spnativeMockLabel;
  spnativeStopTimer();
  spnativeStartTimer();
  spnativeSetPausedUI(false);
  spnativeRenderQuestion();
  showCalcPage('spnativeexam');
}

function spnativeUpdateTimerDisplay(){
  const el = document.getElementById('spnativeExamTimerPill');
  if(!el) return;
  el.textContent = '⏱ ' + spnativeFormatTime(spnativeSession.timeLeft);
  el.classList.toggle('examTimerLow', spnativeSession.timeLeft <= 120);
}
function spnativeStartTimer(){
  spnativeUpdateTimerDisplay();
  spnativeSession.timerId = setInterval(() => {
    spnativeSession.timeLeft--;
    spnativeUpdateTimerDisplay();
    if(spnativeSession.timeLeft <= 0){
      spnativeStopTimer();
      spnativeSubmit();
    }
  }, 1000);
}
function spnativeStopTimer(){
  if(spnativeSession.timerId){ clearInterval(spnativeSession.timerId); spnativeSession.timerId = null; }
}
function spnativeSetPausedUI(paused){
  const btn = document.getElementById('spnativeExamPauseBtn');
  if(btn){
    btn.textContent = paused ? '▶' : '⏸';
    btn.title = paused ? 'Resume Test' : 'Pause Test';
    btn.classList.toggle('paused', paused);
  }
  const overlay = document.getElementById('spnativeExamPauseOverlay');
  if(overlay) overlay.style.display = paused ? 'flex' : 'none';
  ['spnativeExamMarkBtn','spnativeExamClearBtn','spnativeExamSaveNextBtn','spnativeExamSaveNextBtnBottom','spnativeExamSubmitBtn'].forEach(id => {
    const b = document.getElementById(id);
    if(b) b.disabled = paused;
  });
}
function spnativeTogglePause(){
  if(spnativeSession.submitted) return;
  spnativeSession.paused = !spnativeSession.paused;
  if(spnativeSession.paused) spnativeStopTimer(); else spnativeStartTimer();
  spnativeSetPausedUI(spnativeSession.paused);
}
function spnativePaletteState(i){
  const answered = spnativeSession.answers[i] !== null && spnativeSession.answers[i] !== undefined;
  const marked = spnativeSession.marked[i];
  if(marked && answered) return 'pAnsweredMarked';
  if(marked) return 'pMarked';
  if(answered) return 'pAnswered';
  if(spnativeSession.visited[i]) return 'pNotAnswered';
  return '';
}
function spnativeRenderPalette(){
  const grid = document.getElementById('spnativeExamPaletteGrid');
  if(!grid) return;
  grid.innerHTML = '';
  spnativeSession.questions.forEach((q, i) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'examPaletteBtn ' + spnativePaletteState(i) + (i === spnativeSession.current ? ' pCurrent' : '');
    btn.textContent = i + 1;
    btn.addEventListener('click', () => spnativeGoTo(i));
    grid.appendChild(btn);
  });
}
function spnativeRenderQuestion(){
  const q = spnativeSession.questions[spnativeSession.current];
  if(!q) return;
  spnativeSession.visited[spnativeSession.current] = true;
  const qnoEl = document.getElementById('spnativeExamQNo');
  if(qnoEl) qnoEl.textContent = 'Question No. ' + (spnativeSession.current + 1);
  const wordEl = document.getElementById('spnativeExamWordText');
  if(wordEl) wordEl.innerHTML = spnativeQText(q) || '—';
  const isLocked = !!spnativeSession.locked[spnativeSession.current];
  const optList = document.getElementById('spnativeExamOptList');
  if(optList){
    optList.innerHTML = '';
    const selected = spnativeSession.answers[spnativeSession.current];
    (spnativeOpts(q) || []).forEach((opt, i) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      let cls = 'examOptBtn';
      if(isLocked){
        if(i === q.answer) cls += ' correct';
        else if(i === selected) cls += ' wrong';
      } else if(selected === i){
        cls += ' selected';
      }
      btn.className = cls;
      btn.innerHTML = '<span class="examOptMark">' + String.fromCharCode(65 + i) + '</span><span>' + opt + '</span>';
      if(!isLocked) btn.addEventListener('click', () => spnativeSelectOption(i));
      else btn.disabled = true;
      optList.appendChild(btn);
    });
  }
  const solCard = document.getElementById('spnativeExamSolutionCard');
  const solText = document.getElementById('spnativeExamSolutionText');
  const tagWrap = document.getElementById('spnativeExamTagWrap');
  if(isLocked){
    const wasCorrect = selectedIsCorrect(spnativeSession, spnativeSession.current);
    if(tagWrap) tagWrap.innerHTML = '<span class="examReviewTag ' + (wasCorrect ? 'tagCorrect' : 'tagWrong') + '">' + (wasCorrect ? '✅ Correct' : '❌ Incorrect') + '</span>';
    if(solText) solText.innerHTML = spnativeSolText(q) || 'Solution available soon.';
    if(solCard) solCard.style.display = 'block';
  } else {
    if(tagWrap) tagWrap.innerHTML = '';
    if(solCard) solCard.style.display = 'none';
  }
  const markBtn = document.getElementById('spnativeExamMarkBtn');
  if(markBtn) markBtn.textContent = spnativeSession.marked[spnativeSession.current] ? '🚩 Marked ✓' : '🚩 Mark for Review';
  spnativeRenderPalette();
  typesetMath(wordEl); typesetMath(optList); typesetMath(solText);
}
function selectedIsCorrect(session, idx){
  const q = session.questions[idx];
  const a = session.answers[idx];
  return a !== null && a !== undefined && a === q.answer;
}
function spnativeSelectOption(i){
  if(spnativeSession.locked[spnativeSession.current]) return;
  spnativeSession.answers[spnativeSession.current] = i;
  if(spnativeMockModeActive){
    // Mock-style: just record the pick, don't lock/reveal correct-wrong now.
    spnativeRenderQuestion();
    return;
  }
  spnativeSession.locked[spnativeSession.current] = true;
  spnativeRenderQuestion();
}
function spnativeGoTo(idx){
  if(idx < 0 || idx >= spnativeSession.questions.length) return;
  spnativeSession.current = idx;
  spnativeRenderQuestion();
}
function spnativeSaveNext(){
  if(spnativeSession.current < spnativeSession.questions.length - 1) spnativeGoTo(spnativeSession.current + 1);
  else spnativeRenderPalette();
}
function spnativeMarkForReview(){
  spnativeSession.marked[spnativeSession.current] = !spnativeSession.marked[spnativeSession.current];
  if(spnativeSession.current < spnativeSession.questions.length - 1) spnativeGoTo(spnativeSession.current + 1);
  else spnativeRenderQuestion();
}
function spnativeClearResponse(){
  spnativeSession.answers[spnativeSession.current] = null;
  spnativeSession.locked[spnativeSession.current] = false;
  spnativeRenderQuestion();
}
function spnativeConfirmSubmit(){
  const total = spnativeSession.questions.length;
  const answered = spnativeSession.answers.filter(a => a !== null && a !== undefined).length;
  const notAnswered = total - answered;
  const ok = confirm('Answered: ' + answered + '\nNot Answered: ' + notAnswered + '\n\nSubmit test now? Ye action wapas nahi ho sakta.');
  if(ok){ spnativeStopTimer(); spnativeSubmit(); }
}
function spnativeSubmit(){
  if(spnativeSession.submitted) return;
  spnativeSession.submitted = true;
  spnativeStopTimer();
  let correct = 0, wrong = 0, marks = 0;
  spnativeSession.questions.forEach((q, i) => {
    const a = spnativeSession.answers[i];
    if(a === null || a === undefined) return;
    if(a === q.answer){ correct++; marks += (q.marks || 0); }
    else { wrong++; marks -= (q.neg || 0); }
  });
  const skipped = spnativeSession.questions.length - correct - wrong;
  const attempted = correct + wrong;
  const acc = attempted ? Math.round((correct / attempted) * 100) : 0;
  const titleEl = document.getElementById('spnativeResultTitle');
  if(titleEl) titleEl.textContent = spnativeMockLabel;
  const summaryEl = document.getElementById('spnativeExamResultSummary');
  if(summaryEl){
    summaryEl.innerHTML =
      '<div class="examSumCard"><div class="n" style="color:var(--blue);">' + spnativeFormatMarks(marks) + '</div><div class="l">Total Marks</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--gain);">' + correct + '</div><div class="l">Correct</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--loss);">' + wrong + '</div><div class="l">Wrong</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--muted);">' + skipped + '</div><div class="l">Skipped</div></div>' +
      '<div class="examSumCard"><div class="n">' + acc + '%</div><div class="l">Accuracy</div></div>' +
      '<div class="examSumCard"><div class="n">' + spnativeSession.questions.length + '</div><div class="l">Total Qs</div></div>';
  }
  logQuizActivity(spnativeMockLabel, correct, attempted);
  if(spnativeCurrentKey && spnativeCurrentFile) markQuizSetAttempted('spnative', spnativeCurrentKey + '/' + spnativeCurrentFile);
  logSubjectMockToSectional(spnativeCurrentKey, spnativeMockLabel, marks, correct, wrong, skipped, 'Super Practice');
  spnativeResultRenderPalette();
  spnativeResultGoTo(0);
  showCalcPage('spnativeresult');
}
function spnativeResultQState(i){
  const a = spnativeSession.answers[i];
  const q = spnativeSession.questions[i];
  if(a === null || a === undefined) return 'skipped';
  return a === q.answer ? 'correct' : 'wrong';
}
function spnativeResultRenderPalette(){
  const grid = document.getElementById('spnativeResultPaletteGrid');
  if(!grid) return;
  grid.innerHTML = '';
  spnativeSession.questions.forEach((q, i) => {
    const st = spnativeResultQState(i);
    const cls = st === 'correct' ? 'pAnswered' : st === 'wrong' ? 'pNotAnswered' : '';
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'examPaletteBtn ' + cls + (i === spnativeSession.current ? ' pCurrent' : '');
    btn.textContent = i + 1;
    btn.addEventListener('click', () => spnativeResultGoTo(i));
    grid.appendChild(btn);
  });
}
let spnativeResultRevealed = false;
function spnativeResultGoTo(idx){
  if(idx < 0 || idx >= spnativeSession.questions.length) return;
  spnativeSession.current = idx;
  // Mock-mode (quant 25Q mixed) sessions show the answer & solution right
  // away on the result page — no need to tap each question first.
  spnativeResultRevealed = spnativeMockModeActive;
  spnativeResultRenderQuestion();
  spnativeResultRenderPalette();
}
function spnativeResultReveal(){
  if(spnativeResultRevealed) return;
  spnativeResultRevealed = true;
  spnativeResultRenderQuestion();
}
function spnativeResultRenderQuestion(){
  const i = spnativeSession.current;
  const q = spnativeSession.questions[i];
  if(!q) return;
  const qnoEl = document.getElementById('spnativeResultQNo');
  if(qnoEl) qnoEl.textContent = 'Question No. ' + (i + 1);
  const st = spnativeResultQState(i);
  const tagWrap = document.getElementById('spnativeResultTagWrap');
  if(tagWrap){
    if(spnativeResultRevealed){
      const label = st === 'correct' ? '✅ Correct' : st === 'wrong' ? '❌ Incorrect' : '⏭ Skipped';
      const cls = st === 'correct' ? 'tagCorrect' : st === 'wrong' ? 'tagWrong' : 'tagSkipped';
      tagWrap.innerHTML = '<span class="examReviewTag ' + cls + '">' + label + '</span>';
    } else {
      tagWrap.innerHTML = '<span class="examReviewTag" style="background:#3a3742;color:var(--muted);">👆 Tap question to view answer & solution</span>';
    }
  }
  const wordEl = document.getElementById('spnativeResultWordText');
  if(wordEl) wordEl.innerHTML = spnativeQText(q) || '—';
  const optList = document.getElementById('spnativeResultOptList');
  if(optList){
    optList.innerHTML = '';
    const userAns = spnativeSession.answers[i];
    (spnativeOpts(q) || []).forEach((opt, oi) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      let cls = 'examOptBtn';
      if(spnativeResultRevealed){
        if(oi === q.answer) cls += ' correct';
        else if(oi === userAns) cls += ' wrong';
      } else if(oi === userAns){
        cls += ' selected';
      }
      btn.className = cls;
      btn.innerHTML = '<span class="examOptMark">' + String.fromCharCode(65 + oi) + '</span><span>' + opt + '</span>';
      optList.appendChild(btn);
    });
  }
  const solCard = document.getElementById('spnativeResultSolutionCard');
  const solText = document.getElementById('spnativeResultSolutionText');
  if(spnativeResultRevealed){
    if(solText) solText.innerHTML = spnativeSolText(q) || 'Solution available soon.';
    if(solCard) solCard.style.display = 'block';
  } else if(solCard) solCard.style.display = 'none';
  typesetMath(wordEl); typesetMath(optList); typesetMath(solText);
}

function initSuperPracticeQuiz(){
  renderSPSubjectGrid();
  const menuBtn = document.getElementById('calcSuperPracticeBtn');
  if(menuBtn) menuBtn.addEventListener('click', () => showCalcPage('superpracticemenu'));
  const menuBackBtn = document.getElementById('superpracticeMenuBackBtn');
  if(menuBackBtn) menuBackBtn.addEventListener('click', () => showCalcPage('menu'));
  const listBackBtn = document.getElementById('superpracticeListBackBtn');
  if(listBackBtn) listBackBtn.addEventListener('click', () => showCalcPage(spDirectEntry ? (typeof spDirectEntry === 'string' ? spDirectEntry : 'menu') : 'superpracticemenu'));
  const searchBox = document.getElementById('superpracticeSearchInput');
  if(searchBox) searchBox.addEventListener('input', () => filterSPMockGrid(searchBox.value));

  // Native instructions page
  const infoBackBtn = document.getElementById('spnativeInfoBackBtn');
  if(infoBackBtn) infoBackBtn.addEventListener('click', () => showCalcPage('superpracticelist'));
  const startBtn = document.getElementById('spnativeStartBtn');
  if(startBtn) startBtn.addEventListener('click', spnativeStartExam);
  const infoLangBtn = document.getElementById('spnativeInfoLangBtn');
  if(infoLangBtn) infoLangBtn.addEventListener('click', spnativeToggleLang);

  // Native exam page
  const examBackBtn = document.getElementById('spnativeExamBackBtn');
  if(examBackBtn) examBackBtn.addEventListener('click', () => {
    if(confirm('Test chhodna hai? Progress save nahi hoga.')){ spnativeStopTimer(); showCalcPage('superpracticelist'); }
  });
  const pauseBtn = document.getElementById('spnativeExamPauseBtn');
  if(pauseBtn) pauseBtn.addEventListener('click', spnativeTogglePause);
  const resumeBtn = document.getElementById('spnativeExamResumeBtn');
  if(resumeBtn) resumeBtn.addEventListener('click', spnativeTogglePause);
  const submitBtn = document.getElementById('spnativeExamSubmitBtn');
  if(submitBtn) submitBtn.addEventListener('click', spnativeConfirmSubmit);
  const markBtn = document.getElementById('spnativeExamMarkBtn');
  if(markBtn) markBtn.addEventListener('click', spnativeMarkForReview);
  const clearBtn = document.getElementById('spnativeExamClearBtn');
  if(clearBtn) clearBtn.addEventListener('click', spnativeClearResponse);
  const saveNextBtn = document.getElementById('spnativeExamSaveNextBtn');
  if(saveNextBtn) saveNextBtn.addEventListener('click', spnativeSaveNext);
  const saveNextBtnBottom = document.getElementById('spnativeExamSaveNextBtnBottom');
  if(saveNextBtnBottom) saveNextBtnBottom.addEventListener('click', spnativeSaveNext);
  const examLangBtn = document.getElementById('spnativeExamLangBtn');
  if(examLangBtn) examLangBtn.addEventListener('click', spnativeToggleLang);

  // Native result page
  const resultBackBtn = document.getElementById('spnativeResultBackBtn');
  if(resultBackBtn) resultBackBtn.addEventListener('click', () => showCalcPage('superpracticelist'));
  const reattemptBtn = document.getElementById('spnativeResultReattemptBtn');
  if(reattemptBtn) reattemptBtn.addEventListener('click', spnativeStartExam);
  const resultQWrap = document.getElementById('spnativeResultQuestionWrap');
  if(resultQWrap) resultQWrap.addEventListener('click', spnativeResultReveal);
  const resultOptList = document.getElementById('spnativeResultOptList');
  if(resultOptList) resultOptList.addEventListener('click', spnativeResultReveal);
  const resultPrevBtn = document.getElementById('spnativeResultPrevBtn');
  if(resultPrevBtn) resultPrevBtn.addEventListener('click', () => spnativeResultGoTo(spnativeSession.current - 1));
  const resultNextBtn = document.getElementById('spnativeResultNextBtn');
  if(resultNextBtn) resultNextBtn.addEventListener('click', () => spnativeResultGoTo(spnativeSession.current + 1));
  const resultLangBtn = document.getElementById('spnativeResultLangBtn');
  if(resultLangBtn) resultLangBtn.addEventListener('click', spnativeToggleLang);
}

// ===== 75 Day Practice ===== (same pattern as Super Practice, separate pool)
// 384 pre-built, fully self-contained mock-test HTML files bundled under
// practice75/<subject>/mock_NNN.html. practice75/manifest.json lists every
// mock's filename + question count per subject.
const PRACTICE75_SUBJECTS = [
  { key:'quant',     label:'Quant (Math)',            icon:'🧮', count:139 },
  { key:'reasoning', label:'Reasoning',                icon:'🧠', count:65 },
  { key:'english',   label:'English',                  icon:'📘', count:50 },
  { key:'gk',        label:'GK / General Awareness',   icon:'🌍', count:130 },
];
let p75Manifest = null;
let p75CurrentSubjectKey = null;
let p75CurrentSubjectLabel = null;
let p75CurrentEntries = [];

async function ensureP75Manifest(){
  if(p75Manifest) return p75Manifest;
  try{
    const res = await fetch('practice75/manifest.json');
    p75Manifest = await res.json();
  }catch(e){ p75Manifest = {}; }
  return p75Manifest;
}

function renderP75SubjectGrid(){
  const grid = document.getElementById('p75SubjectGrid');
  if(!grid) return;
  grid.innerHTML = '';
  PRACTICE75_SUBJECTS.forEach(s => {
    const btn = document.createElement('button');
    btn.className = 'calcCard calcCard-statement';
    btn.innerHTML =
      '<span class="calcIcon calcIcon-statement">' + s.icon + '</span>' +
      '<span class="calcLabelCol">' +
        '<span class="calcLabel">' + escapeHtml(s.label) + '</span>' +
        '<span class="calcSub">' + s.count + ' mocks</span>' +
      '</span>' +
      '<span class="calcArrow">&#8250;</span>';
    btn.addEventListener('click', () => openP75Subject(s.key, s.label));
    grid.appendChild(btn);
  });
}

async function openP75Subject(key, label){
  p75CurrentSubjectKey = key;
  const titleEl = document.getElementById('p75ListTitle');
  if(titleEl) titleEl.textContent = '🔥 ' + label + ' — Choose a Mock';
  showCalcPage('75daylist');
  const grid = document.getElementById('p75ListGrid');
  if(grid) grid.innerHTML = '<div class="losshint">Loading mocks…</div>';
  const manifest = await ensureP75Manifest();
  const entries = (manifest && manifest[key]) || [];
  p75CurrentSubjectLabel = label;
  p75CurrentEntries = entries;
  const searchBox = document.getElementById('p75SearchInput');
  if(searchBox) searchBox.value = '';
  p75OpenChapter = null;
  renderP75MockGrid(entries);
}

// Groups a subject's mocks by their "topic" field into Oliveboard-style
// chapters — same behaviour as groupSPEntries, used so 75 Days Practice
// shows one button per chapter/topic (with all its mocks inside) instead
// of a flat list.
function groupP75Entries(entries){
  const map = new Map();
  entries.forEach(e => {
    // Prefer the broader "category" (subject-level bucket, e.g. Calculation,
    // Algebra, Polity, Geography) when present; falls back to the raw topic
    // for sections that don't have category tagging yet.
    const key = (e.category || e.topic || 'Mixed Practice').trim();
    if(!map.has(key)) map.set(key, []);
    map.get(key).push(e);
  });
  const chapters = Array.from(map.entries()).map(([topic, items]) => ({ topic, items }));
  chapters.sort((a, b) => {
    if(a.topic === 'Mixed Practice' && b.topic !== 'Mixed Practice') return 1;
    if(b.topic === 'Mixed Practice' && a.topic !== 'Mixed Practice') return -1;
    return a.topic.localeCompare(b.topic);
  });
  return chapters;
}

let p75OpenChapter = null; // currently expanded chapter name, or null

function renderP75MockGrid(entries){
  const grid = document.getElementById('p75ListGrid');
  if(!grid) return;
  grid.classList.remove('calcGrid', 'calcGrid-2col');
  grid.innerHTML = '';
  const chapters = groupP75Entries(entries);
  if(!chapters.length){
    grid.innerHTML = '<div class="losshint">Koi mock nahi mila.</div>';
    return;
  }
  chapters.forEach(ch => {
    const isOpen = p75OpenChapter === ch.topic;
    const wrap = document.createElement('div');
    wrap.style.cssText = 'border:1px solid var(--border);border-radius:12px;margin-bottom:10px;overflow:hidden;background:var(--panel);';

    const header = document.createElement('button');
    header.style.cssText = 'width:100%;display:flex;align-items:center;justify-content:space-between;padding:14px 16px;background:transparent;border:none;text-align:left;font-size:15px;font-weight:600;cursor:pointer;color:inherit;';
    header.innerHTML =
      '<span>' + escapeHtml(ch.topic) + '</span>' +
      '<span style="display:flex;align-items:center;gap:8px;font-weight:400;font-size:13px;color:var(--muted);">' +
        ch.items.length + ' mocks' +
        '<span style="display:inline-block;transform:rotate(' + (isOpen ? 90 : 0) + 'deg);transition:transform .15s;">&#8250;</span>' +
      '</span>';
    header.addEventListener('click', () => {
      p75OpenChapter = isOpen ? null : ch.topic;
      renderP75MockGrid(entries);
    });
    wrap.appendChild(header);

    if(isOpen){
      const body = document.createElement('div');
      body.style.cssText = 'border-top:1px solid var(--border);';
      ch.items.forEach((e, idx) => {
        const done = isQuizSetAttempted('p75native', p75CurrentSubjectKey + '/' + e.file);
        const rowLabel = (e.topic || e.label || ('Level ' + (idx + 1)));
        const row = document.createElement('button');
        row.style.cssText = 'width:100%;display:flex;align-items:center;justify-content:space-between;padding:12px 16px;background:transparent;border:none;border-bottom:1px solid var(--border);text-align:left;cursor:pointer;font-size:14px;color:inherit;';
        row.innerHTML =
          '<span>' + escapeHtml(rowLabel) + (done ? ' <span style="color:var(--gain,#16A34A);">✅</span>' : '') + '</span>' +
          '<span style="color:var(--muted);font-size:13px;">' + e.q + ' Qs &#8250;</span>';
        row.addEventListener('click', () => openP75Mock(p75CurrentSubjectKey, e.file, p75CurrentSubjectLabel, e));
        body.appendChild(row);
      });
      const lastRow = body.lastElementChild;
      if(lastRow) lastRow.style.borderBottom = 'none';
      wrap.appendChild(body);
    }

    grid.appendChild(wrap);
  });
}

function filterP75MockGrid(query){
  const q = (query || '').trim().toLowerCase();
  if(!q){ p75OpenChapter = null; renderP75MockGrid(p75CurrentEntries); return; }
  const filtered = p75CurrentEntries.filter(e => (e.label || '').toLowerCase().includes(q) || (e.topic || '').toLowerCase().includes(q));
  const chapters = groupP75Entries(filtered);
  if(chapters.length === 1) p75OpenChapter = chapters[0].topic;
  renderP75MockGrid(filtered);
}

// ===== 75 Day Practice: native player =====
// Pre-converted data lives at superpractice/data/<key>/mock_NNN.json (see
// extract_sp.py), one JSON per original mock_NNN.html, schema:
//   { title, duration_min, questions: [ { q_en, q_hi, options_en, options_hi,
//     answer(0-based), solution_en, solution_hi, marks, neg } ] }
// Same Testbook-style exam UI as EM Mocks (instructions -> timed exam with
// palette/mark-for-review -> result+solution review), but with a live
// EN/हिंदी toggle since 75 Day Practice source files carry both languages
// (unlike EM Mocks' already-English-only source).
let p75nativeLoaded = null;
let p75nativeMockLabel = '';
let p75nativeCurrentKey = null;
let p75nativeCurrentFile = null;
let p75nativeLang = 'en'; // 'en' | 'hi'
const p75nativeSession = {
  questions: [], answers: [], marked: [], visited: [], revealed: [],
  current: 0, timeLeft: 0, timerId: null, submitted: false, paused: false
};

function p75nativeQText(q){ return p75nativeLang === 'hi' && (q.q_hi || '').trim() ? q.q_hi : q.q_en; }
function p75nativeOpts(q){ return p75nativeLang === 'hi' && nativeHasHiContent(q.options_hi) ? q.options_hi : q.options_en; }
function p75nativeSolText(q){ return p75nativeLang === 'hi' && (q.solution_hi || '').trim() ? q.solution_hi : q.solution_en; }

function p75nativeUpdateLangBtns(){
  const label = p75nativeLang === 'hi' ? '🌐 हिं' : '🌐 EN';
  ['p75nativeInfoLangBtn','p75nativeExamLangBtn','p75nativeResultLangBtn'].forEach(id => {
    const b = document.getElementById(id);
    if(b) b.textContent = label;
  });
}
function p75nativeToggleLang(){
  p75nativeLang = p75nativeLang === 'hi' ? 'en' : 'hi';
  p75nativeUpdateLangBtns();
  // Re-render whichever screen is currently visible with the new language
  const examPage = document.getElementById('calcPage-p75nativeexam');
  const resultPage = document.getElementById('calcPage-p75nativeresult');
  if(examPage && examPage.classList.contains('active')) p75nativeRenderQuestion();
  else if(resultPage && resultPage.classList.contains('active')) p75nativeResultRenderQuestion();
}

async function openP75MockNative(key, file, label, entry){
  p75nativeCurrentKey = key;
  p75nativeCurrentFile = file;
  const p75ExamPageEl = document.getElementById('calcPage-p75nativeexam');
  if(p75ExamPageEl) p75ExamPageEl.dataset.subject = key;
  const p75ResultPageEl = document.getElementById('calcPage-p75nativeresult');
  if(p75ResultPageEl) p75ResultPageEl.dataset.subject = key;
  p75nativeMockLabel = label + ' — ' + (entry.label || ('Mock ' + entry.n));
  const jsonFile = file.replace(/\.html$/, '.json');
  const infoTitleEl = document.getElementById('p75nativeInfoTitle');
  if(infoTitleEl) infoTitleEl.textContent = p75nativeMockLabel;
  p75nativeUpdateLangBtns();
  showCalcPage('p75nativeinfo');
  const qc = document.getElementById('p75nativeInfoQCount'); if(qc) qc.textContent = '…';
  p75nativeLoaded = null;
  const startBtnGate = document.getElementById('p75nativeStartBtn');
  const startBtnGateOldLabel = startBtnGate ? startBtnGate.textContent : '';
  if(startBtnGate){ startBtnGate.disabled = true; startBtnGate.textContent = '⏳ Mock download ho raha hai...'; }
  let data;
  try{
    const res = await fetch('practice75/data/' + key + '/' + jsonFile);
    data = await res.json();
    data = fixMockImagesInData(data);
  }catch(e){
    alert('Ye mock load nahi ho paaya. Dobara try karein.');
    showCalcPage('75daylist');
    return;
  }
  if(!data || !data.questions || !data.questions.length){
    alert('Ye mock abhi available nahi hai.');
    showCalcPage('75daylist');
    return;
  }
  p75nativeLoaded = data;
  if(startBtnGate){ startBtnGate.disabled = false; startBtnGate.textContent = startBtnGateOldLabel || '▶ Start Test'; }
  const totalQ = data.questions.length;
  const totalMarks = data.questions.reduce((s, q) => s + (q.marks || 0), 0);
  const firstQ = data.questions[0] || { marks: 1, neg: 0.25 };
  if(qc) qc.textContent = totalQ;
  const tm = document.getElementById('p75nativeInfoMarks');
  if(tm) tm.textContent = Math.round(totalMarks * 100) / 100;
  const du = document.getElementById('p75nativeInfoDuration');
  if(du) du.textContent = (data.duration_min || 15) + ' minutes';
  const mk = document.getElementById('p75nativeInfoMarking');
  if(mk) mk.textContent = '+' + firstQ.marks + ' / -' + firstQ.neg;
}

function p75nativeFormatMarks(m){ return (Math.round(m * 100) / 100).toString(); }
function p75nativeFormatTime(sec){
  const s = Math.max(0, sec);
  const m = Math.floor(s / 60);
  const r = s % 60;
  return (m < 10 ? '0' + m : m) + ':' + (r < 10 ? '0' + r : r);
}

function p75nativeStartExam(){
  if(!p75nativeLoaded) return;
  p75nativeSession.questions = p75nativeLoaded.questions;
  const n = p75nativeSession.questions.length;
  p75nativeSession.answers = new Array(n).fill(null);
  p75nativeSession.marked = new Array(n).fill(false);
  p75nativeSession.visited = new Array(n).fill(false);
  p75nativeSession.revealed = new Array(n).fill(false);
  p75nativeSession.current = 0;
  p75nativeSession.timeLeft = (p75nativeLoaded.duration_min || 15) * 60;
  p75nativeSession.submitted = false;
  p75nativeSession.paused = false;
  const titleEl = document.getElementById('p75nativeExamTitle');
  if(titleEl) titleEl.textContent = p75nativeMockLabel;
  p75nativeStopTimer();
  p75nativeStartTimer();
  p75nativeSetPausedUI(false);
  p75nativeRenderQuestion();
  showCalcPage('p75nativeexam');
}

function p75nativeUpdateTimerDisplay(){
  const el = document.getElementById('p75nativeExamTimerPill');
  if(!el) return;
  el.textContent = '⏱ ' + p75nativeFormatTime(p75nativeSession.timeLeft);
  el.classList.toggle('examTimerLow', p75nativeSession.timeLeft <= 120);
}
function p75nativeStartTimer(){
  p75nativeUpdateTimerDisplay();
  p75nativeSession.timerId = setInterval(() => {
    p75nativeSession.timeLeft--;
    p75nativeUpdateTimerDisplay();
    if(p75nativeSession.timeLeft <= 0){
      p75nativeStopTimer();
      p75nativeSubmit();
    }
  }, 1000);
}
function p75nativeStopTimer(){
  if(p75nativeSession.timerId){ clearInterval(p75nativeSession.timerId); p75nativeSession.timerId = null; }
}
function p75nativeSetPausedUI(paused){
  const btn = document.getElementById('p75nativeExamPauseBtn');
  if(btn){
    btn.textContent = paused ? '▶' : '⏸';
    btn.title = paused ? 'Resume Test' : 'Pause Test';
    btn.classList.toggle('paused', paused);
  }
  const overlay = document.getElementById('p75nativeExamPauseOverlay');
  if(overlay) overlay.style.display = paused ? 'flex' : 'none';
  ['p75nativeExamMarkBtn','p75nativeExamClearBtn','p75nativeExamSaveNextBtn','p75nativeExamSaveNextBtnBottom','p75nativeExamSubmitBtn'].forEach(id => {
    const b = document.getElementById(id);
    if(b) b.disabled = paused;
  });
}
function p75nativeTogglePause(){
  if(p75nativeSession.submitted) return;
  p75nativeSession.paused = !p75nativeSession.paused;
  if(p75nativeSession.paused) p75nativeStopTimer(); else p75nativeStartTimer();
  p75nativeSetPausedUI(p75nativeSession.paused);
}
function p75nativePaletteState(i){
  const answered = p75nativeSession.answers[i] !== null && p75nativeSession.answers[i] !== undefined;
  const marked = p75nativeSession.marked[i];
  if(marked && answered) return 'pAnsweredMarked';
  if(marked) return 'pMarked';
  if(answered) return 'pAnswered';
  if(p75nativeSession.visited[i]) return 'pNotAnswered';
  return '';
}
function p75nativeRenderPalette(){
  const grid = document.getElementById('p75nativeExamPaletteGrid');
  if(!grid) return;
  grid.innerHTML = '';
  p75nativeSession.questions.forEach((q, i) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'examPaletteBtn ' + p75nativePaletteState(i) + (i === p75nativeSession.current ? ' pCurrent' : '');
    btn.textContent = i + 1;
    btn.addEventListener('click', () => p75nativeGoTo(i));
    grid.appendChild(btn);
  });
}
function p75nativeRenderQuestion(){
  const q = p75nativeSession.questions[p75nativeSession.current];
  if(!q) return;
  p75nativeSession.visited[p75nativeSession.current] = true;
  const qnoEl = document.getElementById('p75nativeExamQNo');
  if(qnoEl) qnoEl.textContent = 'Question No. ' + (p75nativeSession.current + 1);
  const wordEl = document.getElementById('p75nativeExamWordText');
  if(wordEl) wordEl.innerHTML = p75nativeQText(q) || '—';
  const optList = document.getElementById('p75nativeExamOptList');
  const isRevealed = !!p75nativeSession.revealed[p75nativeSession.current];
  if(optList){
    optList.innerHTML = '';
    const selected = p75nativeSession.answers[p75nativeSession.current];
    (p75nativeOpts(q) || []).forEach((opt, i) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      let cls = 'examOptBtn';
      if(isRevealed){
        if(i === q.answer) cls += ' correct';
        else if(i === selected) cls += ' wrong';
      } else if(selected === i){
        cls += ' selected';
      }
      btn.className = cls;
      btn.innerHTML = '<span class="examOptMark">' + String.fromCharCode(65 + i) + '</span><span>' + opt + '</span>';
      if(!isRevealed) btn.addEventListener('click', () => p75nativeSelectOption(i));
      optList.appendChild(btn);
    });
  }
  const solCard = document.getElementById('p75nativeExamSolutionCard');
  const solText = document.getElementById('p75nativeExamSolutionText');
  const solTag = document.getElementById('p75nativeExamSolutionTag');
  if(isRevealed){
    const selected = p75nativeSession.answers[p75nativeSession.current];
    if(solTag) solTag.textContent = (selected === q.answer) ? '✅ Correct — Solution' : '❌ Incorrect — Solution';
    if(solText) solText.innerHTML = p75nativeSolText(q) || 'Solution available soon.';
    if(solCard) solCard.style.display = 'block';
  } else if(solCard) solCard.style.display = 'none';
  const markBtn = document.getElementById('p75nativeExamMarkBtn');
  if(markBtn) markBtn.textContent = p75nativeSession.marked[p75nativeSession.current] ? '🚩 Marked ✓' : '🚩 Mark for Review';
  p75nativeRenderPalette();
  typesetMath(wordEl); typesetMath(optList); typesetMath(solText);
}
function p75nativeSelectOption(i){
  if(p75nativeSession.revealed[p75nativeSession.current]) return; // locked once revealed
  p75nativeSession.answers[p75nativeSession.current] = i;
  p75nativeSession.revealed[p75nativeSession.current] = true;
  p75nativeRenderQuestion();
}
function p75nativeGoTo(idx){
  if(idx < 0 || idx >= p75nativeSession.questions.length) return;
  p75nativeSession.current = idx;
  p75nativeRenderQuestion();
}
function p75nativeSaveNext(){
  if(p75nativeSession.current < p75nativeSession.questions.length - 1) p75nativeGoTo(p75nativeSession.current + 1);
  else p75nativeRenderPalette();
}
function p75nativeMarkForReview(){
  p75nativeSession.marked[p75nativeSession.current] = !p75nativeSession.marked[p75nativeSession.current];
  if(p75nativeSession.current < p75nativeSession.questions.length - 1) p75nativeGoTo(p75nativeSession.current + 1);
  else p75nativeRenderQuestion();
}
function p75nativeClearResponse(){
  p75nativeSession.answers[p75nativeSession.current] = null;
  p75nativeRenderQuestion();
}
function p75nativeConfirmSubmit(){
  const total = p75nativeSession.questions.length;
  const answered = p75nativeSession.answers.filter(a => a !== null && a !== undefined).length;
  const notAnswered = total - answered;
  const ok = confirm('Answered: ' + answered + '\nNot Answered: ' + notAnswered + '\n\nSubmit test now? Ye action wapas nahi ho sakta.');
  if(ok){ p75nativeStopTimer(); p75nativeSubmit(); }
}
function p75nativeSubmit(){
  if(p75nativeSession.submitted) return;
  p75nativeSession.submitted = true;
  p75nativeStopTimer();
  let correct = 0, wrong = 0, marks = 0;
  p75nativeSession.questions.forEach((q, i) => {
    const a = p75nativeSession.answers[i];
    if(a === null || a === undefined) return;
    if(a === q.answer){ correct++; marks += (q.marks || 0); }
    else { wrong++; marks -= (q.neg || 0); }
  });
  const skipped = p75nativeSession.questions.length - correct - wrong;
  const attempted = correct + wrong;
  const acc = attempted ? Math.round((correct / attempted) * 100) : 0;
  const titleEl = document.getElementById('p75nativeResultTitle');
  if(titleEl) titleEl.textContent = p75nativeMockLabel;
  const summaryEl = document.getElementById('p75nativeExamResultSummary');
  if(summaryEl){
    summaryEl.innerHTML =
      '<div class="examSumCard"><div class="n" style="color:var(--blue);">' + p75nativeFormatMarks(marks) + '</div><div class="l">Total Marks</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--gain);">' + correct + '</div><div class="l">Correct</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--loss);">' + wrong + '</div><div class="l">Wrong</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--muted);">' + skipped + '</div><div class="l">Skipped</div></div>' +
      '<div class="examSumCard"><div class="n">' + acc + '%</div><div class="l">Accuracy</div></div>' +
      '<div class="examSumCard"><div class="n">' + p75nativeSession.questions.length + '</div><div class="l">Total Qs</div></div>';
  }
  logQuizActivity(p75nativeMockLabel, correct, attempted);
  if(p75nativeCurrentKey && p75nativeCurrentFile) markQuizSetAttempted('p75native', p75nativeCurrentKey + '/' + p75nativeCurrentFile);
  logSubjectMockToSectional(p75nativeCurrentKey, p75nativeMockLabel, marks, correct, wrong, skipped, '75-Day Practice');
  p75nativeResultRenderPalette();
  p75nativeResultGoTo(0);
  showCalcPage('p75nativeresult');
}
function p75nativeResultQState(i){
  const a = p75nativeSession.answers[i];
  const q = p75nativeSession.questions[i];
  if(a === null || a === undefined) return 'skipped';
  return a === q.answer ? 'correct' : 'wrong';
}
function p75nativeResultRenderPalette(){
  const grid = document.getElementById('p75nativeResultPaletteGrid');
  if(!grid) return;
  grid.innerHTML = '';
  p75nativeSession.questions.forEach((q, i) => {
    const st = p75nativeResultQState(i);
    const cls = st === 'correct' ? 'pAnswered' : st === 'wrong' ? 'pNotAnswered' : '';
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'examPaletteBtn ' + cls + (i === p75nativeSession.current ? ' pCurrent' : '');
    btn.textContent = i + 1;
    btn.addEventListener('click', () => p75nativeResultGoTo(i));
    grid.appendChild(btn);
  });
}
let p75nativeResultRevealed = false;
function p75nativeResultGoTo(idx){
  if(idx < 0 || idx >= p75nativeSession.questions.length) return;
  p75nativeSession.current = idx;
  p75nativeResultRevealed = false;
  p75nativeResultRenderQuestion();
  p75nativeResultRenderPalette();
}
function p75nativeResultReveal(){
  if(p75nativeResultRevealed) return;
  p75nativeResultRevealed = true;
  p75nativeResultRenderQuestion();
}
function p75nativeResultRenderQuestion(){
  const i = p75nativeSession.current;
  const q = p75nativeSession.questions[i];
  if(!q) return;
  const qnoEl = document.getElementById('p75nativeResultQNo');
  if(qnoEl) qnoEl.textContent = 'Question No. ' + (i + 1);
  const st = p75nativeResultQState(i);
  const tagWrap = document.getElementById('p75nativeResultTagWrap');
  if(tagWrap){
    if(p75nativeResultRevealed){
      const label = st === 'correct' ? '✅ Correct' : st === 'wrong' ? '❌ Incorrect' : '⏭ Skipped';
      const cls = st === 'correct' ? 'tagCorrect' : st === 'wrong' ? 'tagWrong' : 'tagSkipped';
      tagWrap.innerHTML = '<span class="examReviewTag ' + cls + '">' + label + '</span>';
    } else {
      tagWrap.innerHTML = '<span class="examReviewTag" style="background:#3a3742;color:var(--muted);">👆 Tap question to view answer & solution</span>';
    }
  }
  const wordEl = document.getElementById('p75nativeResultWordText');
  if(wordEl) wordEl.innerHTML = p75nativeQText(q) || '—';
  const optList = document.getElementById('p75nativeResultOptList');
  if(optList){
    optList.innerHTML = '';
    const userAns = p75nativeSession.answers[i];
    (p75nativeOpts(q) || []).forEach((opt, oi) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      let cls = 'examOptBtn';
      if(p75nativeResultRevealed){
        if(oi === q.answer) cls += ' correct';
        else if(oi === userAns) cls += ' wrong';
      } else if(oi === userAns){
        cls += ' selected';
      }
      btn.className = cls;
      btn.innerHTML = '<span class="examOptMark">' + String.fromCharCode(65 + oi) + '</span><span>' + opt + '</span>';
      optList.appendChild(btn);
    });
  }
  const solCard = document.getElementById('p75nativeResultSolutionCard');
  const solText = document.getElementById('p75nativeResultSolutionText');
  if(p75nativeResultRevealed){
    if(solText) solText.innerHTML = p75nativeSolText(q) || 'Solution available soon.';
    if(solCard) solCard.style.display = 'block';
  } else if(solCard) solCard.style.display = 'none';
  typesetMath(wordEl); typesetMath(optList); typesetMath(solText);
}

function initP75Native(){
  // Native instructions page
  const infoBackBtn = document.getElementById('p75nativeInfoBackBtn');
  if(infoBackBtn) infoBackBtn.addEventListener('click', () => showCalcPage('75daylist'));
  const startBtn = document.getElementById('p75nativeStartBtn');
  if(startBtn) startBtn.addEventListener('click', p75nativeStartExam);
  const infoLangBtn = document.getElementById('p75nativeInfoLangBtn');
  if(infoLangBtn) infoLangBtn.addEventListener('click', p75nativeToggleLang);

  // Native exam page
  const examBackBtn = document.getElementById('p75nativeExamBackBtn');
  if(examBackBtn) examBackBtn.addEventListener('click', () => {
    if(confirm('Test chhodna hai? Progress save nahi hoga.')){ p75nativeStopTimer(); showCalcPage('75daylist'); }
  });
  const pauseBtn = document.getElementById('p75nativeExamPauseBtn');
  if(pauseBtn) pauseBtn.addEventListener('click', p75nativeTogglePause);
  const resumeBtn = document.getElementById('p75nativeExamResumeBtn');
  if(resumeBtn) resumeBtn.addEventListener('click', p75nativeTogglePause);
  const submitBtn = document.getElementById('p75nativeExamSubmitBtn');
  if(submitBtn) submitBtn.addEventListener('click', p75nativeConfirmSubmit);
  const markBtn = document.getElementById('p75nativeExamMarkBtn');
  if(markBtn) markBtn.addEventListener('click', p75nativeMarkForReview);
  const clearBtn = document.getElementById('p75nativeExamClearBtn');
  if(clearBtn) clearBtn.addEventListener('click', p75nativeClearResponse);
  const saveNextBtn = document.getElementById('p75nativeExamSaveNextBtn');
  if(saveNextBtn) saveNextBtn.addEventListener('click', p75nativeSaveNext);
  const saveNextBtnBottom = document.getElementById('p75nativeExamSaveNextBtnBottom');
  if(saveNextBtnBottom) saveNextBtnBottom.addEventListener('click', p75nativeSaveNext);
  const examLangBtn = document.getElementById('p75nativeExamLangBtn');
  if(examLangBtn) examLangBtn.addEventListener('click', p75nativeToggleLang);

  // Native result page
  const resultBackBtn = document.getElementById('p75nativeResultBackBtn');
  if(resultBackBtn) resultBackBtn.addEventListener('click', () => showCalcPage('75daylist'));
  const reattemptBtn = document.getElementById('p75nativeResultReattemptBtn');
  if(reattemptBtn) reattemptBtn.addEventListener('click', p75nativeStartExam);
  const resultQWrap = document.getElementById('p75nativeResultQuestionWrap');
  if(resultQWrap) resultQWrap.addEventListener('click', p75nativeResultReveal);
  const resultOptList = document.getElementById('p75nativeResultOptList');
  if(resultOptList) resultOptList.addEventListener('click', p75nativeResultReveal);
  const resultPrevBtn = document.getElementById('p75nativeResultPrevBtn');
  if(resultPrevBtn) resultPrevBtn.addEventListener('click', () => p75nativeResultGoTo(p75nativeSession.current - 1));
  const resultNextBtn = document.getElementById('p75nativeResultNextBtn');
  if(resultNextBtn) resultNextBtn.addEventListener('click', () => p75nativeResultGoTo(p75nativeSession.current + 1));
  const resultLangBtn = document.getElementById('p75nativeResultLangBtn');
  if(resultLangBtn) resultLangBtn.addEventListener('click', p75nativeToggleLang);
}

function openP75Mock(key, file, label, entry){
  openP75MockNative(key, file, label, entry);
}

function initP75Quiz(){
  renderP75SubjectGrid();
  const menuBtn = document.getElementById('calc75DayBtn');
  if(menuBtn) menuBtn.addEventListener('click', () => showCalcPage('75daymenu'));
  const menuBackBtn = document.getElementById('p75MenuBackBtn');
  if(menuBackBtn) menuBackBtn.addEventListener('click', () => showCalcPage('menu'));
  const listBackBtn = document.getElementById('p75ListBackBtn');
  if(listBackBtn) listBackBtn.addEventListener('click', () => showCalcPage('75daymenu'));
  const searchBox = document.getElementById('p75SearchInput');
  if(searchBox) searchBox.addEventListener('input', () => filterP75MockGrid(searchBox.value));
  initP75Native();
}

// ===== Mains Mock ===== (same iframe pattern as Super Practice / 75 Day Practice)
// Two pools of pre-built, fully self-contained mock-test HTML files:
//   mainsmock/sectional/mock_NNN.html — Pinnacle sectional mocks (97)
//   mainsmock/full/mock_NNN.html      — Olive SSC CGL Tier II full mocks (71)
// mainsmock/manifest.json = { sectional: [...], full: [...] }
const MAINSMOCK_TYPES = [
  { key:'sectional', label:'Math + Reasoning', icon:'📝', count:97 },
  { key:'full',       label:'Full Mock',      icon:'📘', count:71 },
];
let mainsmockManifest = null;
let mainsmockCurrentTypeKey = null;
let mainsmockCurrentTypeLabel = null;
let mainsmockCurrentEntries = [];

async function ensureMainsMockManifest(){
  if(mainsmockManifest) return mainsmockManifest;
  try{
    const res = await fetch('mainsmock/manifest.json');
    mainsmockManifest = await res.json();
  }catch(e){ mainsmockManifest = {}; }
  return mainsmockManifest;
}

function renderMainsMockTypeGrid(){
  const grid = document.getElementById('mainsmockTypeGrid');
  if(!grid) return;
  grid.innerHTML = '';
  MAINSMOCK_TYPES.forEach(s => {
    const btn = document.createElement('button');
    btn.className = 'calcCard calcCard-statement';
    btn.innerHTML =
      '<span class="calcIcon calcIcon-statement">' + s.icon + '</span>' +
      '<span class="calcLabelCol">' +
        '<span class="calcLabel">' + escapeHtml(s.label) + '</span>' +
        '<span class="calcSub">' + s.count + ' mocks</span>' +
      '</span>' +
      '<span class="calcArrow">&#8250;</span>';
    btn.addEventListener('click', () => openMainsMockType(s.key, s.label));
    grid.appendChild(btn);
  });
}

async function openMainsMockType(key, label){
  mainsmockCurrentTypeKey = key;
  const titleEl = document.getElementById('mainsmockListTitle');
  if(titleEl) titleEl.textContent = '🎯 ' + label + ' — Choose a Mock';
  showCalcPage('mainsmocklist');
  const grid = document.getElementById('mainsmockListGrid');
  if(grid) grid.innerHTML = '<div class="losshint">Loading mocks…</div>';
  const manifest = await ensureMainsMockManifest();
  const entries = (manifest && manifest[key]) || [];
  mainsmockCurrentTypeLabel = label;
  mainsmockCurrentEntries = entries;
  const searchBox = document.getElementById('mainsmockSearchInput');
  if(searchBox) searchBox.value = '';
  renderMainsMockGrid(entries);
}

function renderMainsMockGrid(entries){
  const grid = document.getElementById('mainsmockListGrid');
  if(!grid) return;
  grid.innerHTML = '';
  entries.forEach(e => {
    const done = isQuizSetAttempted('mmnative', mainsmockCurrentTypeKey + '/' + e.file);
    const btn = document.createElement('button');
    btn.className = 'calcCard calcCard-vocab';
    btn.style.flexDirection = 'column';
    btn.style.alignItems = 'flex-start';
    btn.style.gap = '2px';
    btn.innerHTML =
      '<span class="calcLabel">' + escapeHtml(e.label || ('Mock ' + e.n)) + (done ? ' <span style="color:var(--gain,#16A34A);">✅</span>' : '') + '</span>' +
      '<span class="calcSub">' + e.q + ' Qs</span>';
    btn.addEventListener('click', () => openMainsMock(mainsmockCurrentTypeKey, e.file, mainsmockCurrentTypeLabel, e));
    grid.appendChild(btn);
  });
  if(!entries.length){
    grid.innerHTML = '<div class="losshint">Koi mock nahi mila.</div>';
  }
}

function filterMainsMockGrid(query){
  const q = (query || '').trim().toLowerCase();
  if(!q){ renderMainsMockGrid(mainsmockCurrentEntries); return; }
  const filtered = mainsmockCurrentEntries.filter(e => (e.label || '').toLowerCase().includes(q) || (e.topic || '').toLowerCase().includes(q));
  renderMainsMockGrid(filtered);
}

// ===== Mains Mock: native player =====
// Pre-converted data lives at superpractice/data/<key>/mock_NNN.json (see
// extract_sp.py), one JSON per original mock_NNN.html, schema:
//   { title, duration_min, questions: [ { q_en, q_hi, options_en, options_hi,
//     answer(0-based), solution_en, solution_hi, marks, neg } ] }
// Same Testbook-style exam UI as EM Mocks (instructions -> timed exam with
// palette/mark-for-review -> result+solution review), but with a live
// EN/हिंदी toggle since Mains Mock source files carry both languages
// (unlike EM Mocks' already-English-only source).
let mmnativeLoaded = null;
let mmnativeMockLabel = '';
let mmnativeCurrentKey = null;
let mmnativeCurrentFile = null;
let mmnativeLang = 'en'; // 'en' | 'hi'
const mmnativeSession = {
  questions: [], answers: [], marked: [], visited: [],
  current: 0, timeLeft: 0, timerId: null, submitted: false, paused: false,
  sections: null, sectionIdx: 0, sectionTimeLeft: 0, sectionSubmitted: []
};

function mmnativeQText(q){ return mmnativeLang === 'hi' && (q.q_hi || '').trim() ? q.q_hi : q.q_en; }
function mmnativeOpts(q){ return mmnativeLang === 'hi' && nativeHasHiContent(q.options_hi) ? q.options_hi : q.options_en; }
function mmnativeSolText(q){ return mmnativeLang === 'hi' && (q.solution_hi || '').trim() ? q.solution_hi : q.solution_en; }

function mmnativeUpdateLangBtns(){
  const label = mmnativeLang === 'hi' ? '🌐 हिं' : '🌐 EN';
  ['mmnativeInfoLangBtn','mmnativeExamLangBtn','mmnativeResultLangBtn'].forEach(id => {
    const b = document.getElementById(id);
    if(b) b.textContent = label;
  });
}
function mmnativeToggleLang(){
  mmnativeLang = mmnativeLang === 'hi' ? 'en' : 'hi';
  mmnativeUpdateLangBtns();
  // Re-render whichever screen is currently visible with the new language
  const examPage = document.getElementById('calcPage-mmnativeexam');
  const resultPage = document.getElementById('calcPage-mmnativeresult');
  if(examPage && examPage.classList.contains('active')) mmnativeRenderQuestion();
  else if(resultPage && resultPage.classList.contains('active')) mmnativeResultRenderQuestion();
}

async function openMainsMockNative(key, file, label, entry){
  mmnativeCurrentKey = key;
  mmnativeCurrentFile = file;
  mmnativeMockLabel = label + ' — ' + (entry.label || ('Mock ' + entry.n));
  const jsonFile = file.replace(/\.html$/, '.json');
  const infoTitleEl = document.getElementById('mmnativeInfoTitle');
  if(infoTitleEl) infoTitleEl.textContent = mmnativeMockLabel;
  mmnativeUpdateLangBtns();
  showCalcPage('mmnativeinfo');
  document.body.classList.toggle('lightExamTheme', true); // Mains Mock: light theme for both sectional and full mocks
  const qc = document.getElementById('mmnativeInfoQCount'); if(qc) qc.textContent = '…';
  let data;
  try{
    const res = await fetch('mainsmock/data/' + key + '/' + jsonFile);
    data = await res.json();
    data = fixMockImagesInData(data);
  }catch(e){
    alert('Ye mock load nahi ho paaya. Dobara try karein.');
    showCalcPage('mainsmocklist');
    return;
  }
  if(!data || !data.questions || !data.questions.length){
    alert('Ye mock abhi available nahi hai.');
    showCalcPage('mainsmocklist');
    return;
  }
  mmnativeLoaded = data;
  const totalQ = data.questions.length;
  const totalMarks = data.questions.reduce((s, q) => s + (q.marks || 0), 0);
  const firstQ = data.questions[0] || { marks: 1, neg: 0.25 };
  if(qc) qc.textContent = totalQ;
  const tm = document.getElementById('mmnativeInfoMarks');
  if(tm) tm.textContent = Math.round(totalMarks * 100) / 100;
  const du = document.getElementById('mmnativeInfoDuration');
  if(du){
    if(key === 'sectional') du.textContent = '15 + 15 min (Math then Reasoning, sectional)';
    else if(key === 'full') du.textContent = '30+30+30+30+15 min — Sec I (Quant/Reasoning) → Sec II (English/GK) → Sec III (Computer)';
    else du.textContent = (data.duration_min || 15) + ' minutes';
  }
  const mk = document.getElementById('mmnativeInfoMarking');
  if(mk) mk.textContent = '+' + firstQ.marks + ' / -' + firstQ.neg;
}

function mmnativeFormatMarks(m){ return (Math.round(m * 100) / 100).toString(); }
function mmnativeFormatTime(sec){
  const s = Math.max(0, sec);
  const m = Math.floor(s / 60);
  const r = s % 60;
  return (m < 10 ? '0' + m : m) + ':' + (r < 10 ? '0' + r : r);
}

function mmnativeStartExam(){
  if(!mmnativeLoaded) return;
  mmnativeSession.questions = mmnativeLoaded.questions;
  const n = mmnativeSession.questions.length;
  mmnativeSession.answers = new Array(n).fill(null);
  mmnativeSession.marked = new Array(n).fill(false);
  mmnativeSession.visited = new Array(n).fill(false);
  mmnativeSession.submitted = false;
  mmnativeSession.paused = false;
  // Sectional Mocks (Math + Reasoning, 60 Qs) get split into two timed
  // sections — Q1..half = Math (30 min), half+1..end = Reasoning (30 min).
  // Once a section's time is up (or it's manually submitted), those
  // questions lock and the next section auto-opens with a fresh timer —
  // just like the real Tier-II module-wise exam. "Full Mock" (and anything
  // else) keeps the old single continuous timer for the whole paper.
  if(mmnativeCurrentKey === 'sectional' && n >= 2){
    const half = Math.round(n / 2);
    mmnativeSession.sections = [
      { name: 'Math', start: 0, end: half, minutes: 15, sectionLabel: null }
    ];
    mmnativeSession.sections.push({ name: 'Reasoning', start: half, end: n, minutes: 15, sectionLabel: null });
    mmnativeSession.sectionIdx = 0;
    mmnativeSession.sectionSubmitted = mmnativeSession.sections.map(() => false);
    mmnativeSession.sectionTimeLeft = mmnativeSession.sections[0].minutes * 60;
    mmnativeSession.current = mmnativeSession.sections[0].start;
  } else if(mmnativeCurrentKey === 'full' && n === 150){
    // Official TCS CBT pattern: Section I (Quant 30 + Reasoning 30, 30 min
    // each) -> Section II (English 45, 40 min + GK 25, 20 min) -> Section III
    // (Computer Knowledge 20, 15 min). Each subject is its own locked
    // module — once you move to the next module the previous one (and its
    // whole section) is permanently locked, exactly like the real exam.
    mmnativeSession.sections = [
      { name: 'Quantitative Aptitude', start: 0,   end: 30,  minutes: 30, sectionLabel: 'Section I' },
      { name: 'Reasoning',             start: 30,  end: 60,  minutes: 30, sectionLabel: 'Section I' },
      { name: 'English Language',      start: 60,  end: 105, minutes: 40, sectionLabel: 'Section II' },
      { name: 'General Awareness',     start: 105, end: 130, minutes: 20, sectionLabel: 'Section II' },
      { name: 'Computer Knowledge',    start: 130, end: 150, minutes: 15, sectionLabel: 'Section III' }
    ];
    mmnativeSession.sectionIdx = 0;
    mmnativeSession.sectionSubmitted = mmnativeSession.sections.map(() => false);
    mmnativeSession.sectionTimeLeft = mmnativeSession.sections[0].minutes * 60;
    mmnativeSession.current = mmnativeSession.sections[0].start;
  } else {
    mmnativeSession.sections = null;
    mmnativeSession.current = 0;
    mmnativeSession.timeLeft = (mmnativeLoaded.duration_min || 15) * 60;
  }
  const titleEl = document.getElementById('mmnativeExamTitle');
  if(titleEl) titleEl.textContent = mmnativeMockLabel;
  mmnativeStopTimer();
  mmnativeStartTimer();
  mmnativeSetPausedUI(false);
  mmnativeRenderQuestion();
  showCalcPage('mmnativeexam');
  document.body.classList.toggle('lightExamTheme', true); // Mains Mock: light theme for both sectional and full mocks
}

function mmnativeUpdateTimerDisplay(){
  const el = document.getElementById('mmnativeExamTimerPill');
  if(!el) return;
  const t = mmnativeSession.sections ? mmnativeSession.sectionTimeLeft : mmnativeSession.timeLeft;
  el.textContent = '⏱ ' + mmnativeFormatTime(t);
  el.classList.toggle('examTimerLow', t <= 120);
}
function mmnativeStartTimer(){
  mmnativeUpdateTimerDisplay();
  mmnativeSession.timerId = setInterval(() => {
    if(mmnativeSession.sections){
      mmnativeSession.sectionTimeLeft--;
      mmnativeUpdateTimerDisplay();
      if(mmnativeSession.sectionTimeLeft <= 0){
        mmnativeAdvanceSection();
      }
    } else {
      mmnativeSession.timeLeft--;
      mmnativeUpdateTimerDisplay();
      if(mmnativeSession.timeLeft <= 0){
        mmnativeStopTimer();
        mmnativeSubmit();
      }
    }
  }, 1000);
}
function mmnativeStopTimer(){
  if(mmnativeSession.timerId){ clearInterval(mmnativeSession.timerId); mmnativeSession.timerId = null; }
}
// Called when a section's 30-min timer runs out (or the user manually
// submits that section). Locks that section's answers, then either opens
// the next section with a fresh timer, or — if it was the last section —
// finalizes the whole mock via mmnativeSubmit().
function mmnativeAdvanceSection(){
  if(!mmnativeSession.sections) return;
  mmnativeSession.sectionSubmitted[mmnativeSession.sectionIdx] = true;
  const isLast = mmnativeSession.sectionIdx >= mmnativeSession.sections.length - 1;
  if(isLast){
    mmnativeStopTimer();
    mmnativeSubmit();
    return;
  }
  mmnativeSession.sectionIdx++;
  const prev = mmnativeSession.sections[mmnativeSession.sectionIdx - 1];
  const sec = mmnativeSession.sections[mmnativeSession.sectionIdx];
  mmnativeSession.sectionTimeLeft = sec.minutes * 60;
  mmnativeSession.current = sec.start;
  const enteringNewSection = sec.sectionLabel && sec.sectionLabel !== prev.sectionLabel;
  const msg = '⏱ ' + prev.name + ' module submit ho gaya, ab locked hai.\n\n' +
    (enteringNewSection ? '➡️ ' + sec.sectionLabel + ' shuru — ' : '➡️ Ab ') +
    sec.name + ' module — ' + sec.minutes + ' minute.';
  alert(msg);
  mmnativeRenderQuestion();
}
function mmnativeConfirmSubmitSection(){
  if(!mmnativeSession.sections) return;
  const sec = mmnativeSession.sections[mmnativeSession.sectionIdx];
  const isLast = mmnativeSession.sectionIdx >= mmnativeSession.sections.length - 1;
  const answered = mmnativeSession.answers.slice(sec.start, sec.end).filter(a => a !== null && a !== undefined).length;
  const markedCount = mmnativeSession.marked.slice(sec.start, sec.end).filter(Boolean).length;
  const notAnswered = (sec.end - sec.start) - answered;
  const nextName = isLast ? null : mmnativeSession.sections[mmnativeSession.sectionIdx + 1].name;
  const msg = 'Attempted: ' + answered + '\nNot Attempted: ' + notAnswered + '\nMarked for Review: ' + markedCount + '\n\n' +
    (isLast ? 'Submit test now? Ye action wapas nahi ho sakta.' : sec.name + ' module submit karke ' + nextName + ' module shuru karein? ' + sec.name + ' ke baad wapas edit nahi ho sakega.');
  if(confirm(msg)) mmnativeAdvanceSection();
}
function mmnativeSetPausedUI(paused){
  const btn = document.getElementById('mmnativeExamPauseBtn');
  if(btn){
    btn.textContent = paused ? '▶' : '⏸';
    btn.title = paused ? 'Resume Test' : 'Pause Test';
    btn.classList.toggle('paused', paused);
  }
  const overlay = document.getElementById('mmnativeExamPauseOverlay');
  if(overlay) overlay.style.display = paused ? 'flex' : 'none';
  ['mmnativeExamMarkBtn','mmnativeExamClearBtn','mmnativeExamSaveNextBtn','mmnativeExamSaveNextBtnBottom','mmnativeExamSubmitBtn'].forEach(id => {
    const b = document.getElementById(id);
    if(b) b.disabled = paused;
  });
}
function mmnativeTogglePause(){
  if(mmnativeSession.submitted) return;
  mmnativeSession.paused = !mmnativeSession.paused;
  if(mmnativeSession.paused) mmnativeStopTimer(); else mmnativeStartTimer();
  mmnativeSetPausedUI(mmnativeSession.paused);
}
function mmnativePaletteState(i){
  const answered = mmnativeSession.answers[i] !== null && mmnativeSession.answers[i] !== undefined;
  const marked = mmnativeSession.marked[i];
  if(marked && answered) return 'pAnsweredMarked';
  if(marked) return 'pMarked';
  if(answered) return 'pAnswered';
  if(mmnativeSession.visited[i]) return 'pNotAnswered';
  return '';
}
function mmnativeRenderPalette(){
  const grid = document.getElementById('mmnativeExamPaletteGrid');
  if(!grid) return;
  grid.innerHTML = '';
  const range = mmnativeSession.sections
    ? [mmnativeSession.sections[mmnativeSession.sectionIdx].start, mmnativeSession.sections[mmnativeSession.sectionIdx].end]
    : [0, mmnativeSession.questions.length];
  mmnativeSession.questions.forEach((q, i) => {
    if(i < range[0] || i >= range[1]) return; // dusre section ke questions is view me nahi aate
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'examPaletteBtn ' + mmnativePaletteState(i) + (i === mmnativeSession.current ? ' pCurrent' : '');
    btn.textContent = i + 1;
    btn.addEventListener('click', () => mmnativeGoTo(i));
    grid.appendChild(btn);
  });
}
function mmnativeRenderQuestion(){
  const q = mmnativeSession.questions[mmnativeSession.current];
  if(!q) return;
  mmnativeSession.visited[mmnativeSession.current] = true;
  const qnoEl = document.getElementById('mmnativeExamQNo');
  if(qnoEl) qnoEl.textContent = 'Question No. ' + (mmnativeSession.current + 1);
  const badgeEl = document.getElementById('mmnativeExamExamBadge');
  if(badgeEl){
    if(mmnativeSession.sections){
      const sec = mmnativeSession.sections[mmnativeSession.sectionIdx];
      const siblings = mmnativeSession.sections.filter(s => s.sectionLabel === sec.sectionLabel);
      const tabsTxt = siblings.length > 1
        ? siblings.map(s => s.name === sec.name ? '● ' + s.name : '🔒 ' + s.name).join('   |   ')
        : sec.name;
      badgeEl.innerHTML = (sec.sectionLabel ? '🔥 ' + sec.sectionLabel + ' — ' : '🔥 ') +
        '<div style="font-size:12px;font-weight:600;margin-top:4px;color:var(--muted);">' + escapeHtml(tabsTxt) + ' (Q' + (sec.start + 1) + '-' + sec.end + ')</div>';
    } else {
      badgeEl.textContent = '🔥 Mains Mock';
    }
  }
  const wordEl = document.getElementById('mmnativeExamWordText');
  if(wordEl) wordEl.innerHTML = mmnativeQText(q) || '—';
  const optList = document.getElementById('mmnativeExamOptList');
  if(optList){
    optList.innerHTML = '';
    const selected = mmnativeSession.answers[mmnativeSession.current];
    (mmnativeOpts(q) || []).forEach((opt, i) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'examOptBtn' + (selected === i ? ' selected' : '');
      btn.innerHTML = '<span class="examOptMark">' + String.fromCharCode(65 + i) + '</span><span>' + opt + '</span>';
      btn.addEventListener('click', () => mmnativeSelectOption(i));
      optList.appendChild(btn);
    });
  }
  const markBtn = document.getElementById('mmnativeExamMarkBtn');
  if(markBtn) markBtn.textContent = mmnativeSession.marked[mmnativeSession.current] ? '🚩 Marked ✓' : '🚩 Mark for Review';
  const submitBtn = document.getElementById('mmnativeExamSubmitBtn');
  if(submitBtn && mmnativeSession.sections){
    const isLast = mmnativeSession.sectionIdx >= mmnativeSession.sections.length - 1;
    submitBtn.textContent = isLast ? 'Submit Test' : 'Submit ' + mmnativeSession.sections[mmnativeSession.sectionIdx].name;
  }
  mmnativeRenderPalette();
  typesetMath(wordEl); typesetMath(optList);
}
function mmnativeSelectOption(i){
  mmnativeSession.answers[mmnativeSession.current] = i;
  mmnativeRenderQuestion();
}
function mmnativeGoTo(idx){
  if(idx < 0 || idx >= mmnativeSession.questions.length) return;
  if(mmnativeSession.sections){
    const sec = mmnativeSession.sections[mmnativeSession.sectionIdx];
    if(idx < sec.start || idx >= sec.end) return; // dusre section me jaana allowed nahi jab tak current section submit na ho
  }
  mmnativeSession.current = idx;
  mmnativeRenderQuestion();
}
function mmnativeSaveNext(){
  const lastIdx = mmnativeSession.sections ? mmnativeSession.sections[mmnativeSession.sectionIdx].end - 1 : mmnativeSession.questions.length - 1;
  if(mmnativeSession.current < lastIdx) mmnativeGoTo(mmnativeSession.current + 1);
  else mmnativeRenderPalette();
}
function mmnativeMarkForReview(){
  mmnativeSession.marked[mmnativeSession.current] = !mmnativeSession.marked[mmnativeSession.current];
  const lastIdx = mmnativeSession.sections ? mmnativeSession.sections[mmnativeSession.sectionIdx].end - 1 : mmnativeSession.questions.length - 1;
  if(mmnativeSession.current < lastIdx) mmnativeGoTo(mmnativeSession.current + 1);
  else mmnativeRenderQuestion();
}
function mmnativeClearResponse(){
  mmnativeSession.answers[mmnativeSession.current] = null;
  mmnativeRenderQuestion();
}
function mmnativeConfirmSubmit(){
  if(mmnativeSession.sections){
    mmnativeConfirmSubmitSection();
    return;
  }
  const total = mmnativeSession.questions.length;
  const answered = mmnativeSession.answers.filter(a => a !== null && a !== undefined).length;
  const notAnswered = total - answered;
  const ok = confirm('Answered: ' + answered + '\nNot Answered: ' + notAnswered + '\n\nSubmit test now? Ye action wapas nahi ho sakta.');
  if(ok){ mmnativeStopTimer(); mmnativeSubmit(); }
}
function mmnativeSubmit(){
  if(mmnativeSession.submitted) return;
  mmnativeSession.submitted = true;
  mmnativeStopTimer();
  let correct = 0, wrong = 0, marks = 0;
  mmnativeSession.questions.forEach((q, i) => {
    const a = mmnativeSession.answers[i];
    if(a === null || a === undefined) return;
    if(a === q.answer){ correct++; marks += (q.marks || 0); }
    else { wrong++; marks -= (q.neg || 0); }
  });
  const skipped = mmnativeSession.questions.length - correct - wrong;
  const attempted = correct + wrong;
  const acc = attempted ? Math.round((correct / attempted) * 100) : 0;
  const titleEl = document.getElementById('mmnativeResultTitle');
  if(titleEl) titleEl.textContent = mmnativeMockLabel;
  const summaryEl = document.getElementById('mmnativeExamResultSummary');
  if(summaryEl){
    summaryEl.innerHTML =
      '<div class="examSumCard"><div class="n" style="color:var(--blue);">' + mmnativeFormatMarks(marks) + '</div><div class="l">Total Marks</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--gain);">' + correct + '</div><div class="l">Correct</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--loss);">' + wrong + '</div><div class="l">Wrong</div></div>' +
      '<div class="examSumCard"><div class="n" style="color:var(--muted);">' + skipped + '</div><div class="l">Skipped</div></div>' +
      '<div class="examSumCard"><div class="n">' + acc + '%</div><div class="l">Accuracy</div></div>' +
      '<div class="examSumCard"><div class="n">' + mmnativeSession.questions.length + '</div><div class="l">Total Qs</div></div>';
  }
  logQuizActivity(mmnativeMockLabel, correct, attempted);
  if(mmnativeCurrentKey && mmnativeCurrentFile) markQuizSetAttempted('mmnative', mmnativeCurrentKey + '/' + mmnativeCurrentFile);
  mmnativeResultRenderPalette();
  mmnativeResultGoTo(0);
  showCalcPage('mmnativeresult');
  document.body.classList.toggle('lightExamTheme', true); // Mains Mock: light theme for both sectional and full mocks
}
function mmnativeResultQState(i){
  const a = mmnativeSession.answers[i];
  const q = mmnativeSession.questions[i];
  if(a === null || a === undefined) return 'skipped';
  return a === q.answer ? 'correct' : 'wrong';
}
function mmnativeResultRenderPalette(){
  const grid = document.getElementById('mmnativeResultPaletteGrid');
  if(!grid) return;
  grid.innerHTML = '';
  mmnativeSession.questions.forEach((q, i) => {
    const st = mmnativeResultQState(i);
    const cls = st === 'correct' ? 'pAnswered' : st === 'wrong' ? 'pNotAnswered' : '';
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'examPaletteBtn ' + cls + (i === mmnativeSession.current ? ' pCurrent' : '');
    btn.textContent = i + 1;
    btn.addEventListener('click', () => mmnativeResultGoTo(i));
    grid.appendChild(btn);
  });
}
let mmnativeResultRevealed = false;
function mmnativeResultGoTo(idx){
  if(idx < 0 || idx >= mmnativeSession.questions.length) return;
  mmnativeSession.current = idx;
  mmnativeResultRevealed = false;
  mmnativeResultRenderQuestion();
  mmnativeResultRenderPalette();
}
function mmnativeResultReveal(){
  if(mmnativeResultRevealed) return;
  mmnativeResultRevealed = true;
  mmnativeResultRenderQuestion();
}
function mmnativeResultRenderQuestion(){
  const i = mmnativeSession.current;
  const q = mmnativeSession.questions[i];
  if(!q) return;
  const qnoEl = document.getElementById('mmnativeResultQNo');
  if(qnoEl) qnoEl.textContent = 'Question No. ' + (i + 1);
  const st = mmnativeResultQState(i);
  const tagWrap = document.getElementById('mmnativeResultTagWrap');
  if(tagWrap){
    if(mmnativeResultRevealed){
      const label = st === 'correct' ? '✅ Correct' : st === 'wrong' ? '❌ Incorrect' : '⏭ Skipped';
      const cls = st === 'correct' ? 'tagCorrect' : st === 'wrong' ? 'tagWrong' : 'tagSkipped';
      tagWrap.innerHTML = '<span class="examReviewTag ' + cls + '">' + label + '</span>';
    } else {
      tagWrap.innerHTML = '<span class="examReviewTag" style="background:#3a3742;color:var(--muted);">👆 Tap question to view answer & solution</span>';
    }
  }
  const wordEl = document.getElementById('mmnativeResultWordText');
  if(wordEl) wordEl.innerHTML = mmnativeQText(q) || '—';
  const optList = document.getElementById('mmnativeResultOptList');
  if(optList){
    optList.innerHTML = '';
    const userAns = mmnativeSession.answers[i];
    (mmnativeOpts(q) || []).forEach((opt, oi) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      let cls = 'examOptBtn';
      if(mmnativeResultRevealed){
        if(oi === q.answer) cls += ' correct';
        else if(oi === userAns) cls += ' wrong';
      } else if(oi === userAns){
        cls += ' selected';
      }
      btn.className = cls;
      btn.innerHTML = '<span class="examOptMark">' + String.fromCharCode(65 + oi) + '</span><span>' + opt + '</span>';
      optList.appendChild(btn);
    });
  }
  const solCard = document.getElementById('mmnativeResultSolutionCard');
  const solText = document.getElementById('mmnativeResultSolutionText');
  if(mmnativeResultRevealed){
    if(solText) solText.innerHTML = mmnativeSolText(q) || 'Solution available soon.';
    if(solCard) solCard.style.display = 'block';
  } else if(solCard) solCard.style.display = 'none';
  typesetMath(wordEl); typesetMath(optList); typesetMath(solText);
}

