    sp.style.display = on ? 'block' : 'none';
    if(st){ st.box = $('cxCam').querySelector('.cv').getBoundingClientRect(); if(st.spf == null) st.spf = .5; sp.style.left = (st.spf * 100) + '%'; }
    if(!Q.hist && !Q.clip && st){ st.hc = 0; }
