    let cHi = 0, cLo = 0, cim = null, cd = null, cc = null;
    if(Q.clip){ cc = $('cxClip'); if(cc.width !== W || cc.height !== H){ cc.width = W; cc.height = H; } cim = cc.getContext('2d').createImageData(W, H); cd = cim.data; }
