      let s = 0; cnt = 0;
      for(let y = y0; y < y1; y += 2){ const r = y * W, r2 = (y + oy) * W + ox; for(let x = x0; x < x1; x += 2){ const a = g[r + x] - p[r2 + x]; s += a < 0 ? -a : a; cnt++; } }
