      const dx = (f.x - p.x) / dt / fwn, dy = (f.y - p.y) / dt / fwn;
      oeDx[i] += (dx - oeDx[i]) * aD; oeDy[i] += (dy - oeDy[i]) * aD;
      const a = oeA(OE_MIN + OE_BETA * Math.hypot(oeDx[i], oeDy[i]), dt);
