// ============================================================================
// CHAT PLUS 17: GALLERY SAVE (camera + chat media) + draw mode me sab controls chalte hain
//   - Camera se photo/video lete hi apne aap phone me save (localStorage 'cxAutoGal' = '0' kare to band).
//   - Chat ke har photo/video ke neeche "⬇ Gallery" button + viewer ka ⬇ bhi seedha save karta hai.
//   - Android: file Downloads me jati hai aur Gallery/Photos me "Download" album me dikhti hai.
//   - iPhone: browser seedha gallery me nahi likh sakta -> Share sheet khulti hai, "Save Image/Video" dabao.
//   - Draw mode (HandWrite): send, +, camera, menu, header sab ke taps ab seedha kaam karte hain.
// ============================================================================
(function cxGallery(){
  const toast = (m)=>{ try{ chatToastMsg(m); }catch(e){} };
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  const EXT = { 'image/jpeg':'jpg', 'image/png':'png', 'image/webp':'webp', 'image/gif':'gif', 'video/mp4':'mp4', 'video/webm':'webm', 'video/quicktime':'mov' };

  async function toBlob(src){
    if(src instanceof Blob) return src;
    if(typeof src === 'string'){ const r = await fetch(src); return await r.blob(); }
    throw new Error('bad src');
  }
  function fixName(name, blob, kind){
    let n = String(name || '').replace(/[\\/:*?"<>|]+/g, '_');
    const ext = EXT[blob.type] || (kind === 'v' ? 'webm' : 'jpg');
    if(!/\.[a-z0-9]{2,4}$/i.test(n)) n = (n && n !== 'file' ? n : 'chat_' + Date.now()) + '.' + ext;
    return n;
  }
  async function save(src, name, kind, quiet){
    try{
      const blob = await toBlob(src);
      const fname = fixName(name, blob, kind);
      const file = new File([blob], fname, { type: blob.type || (kind === 'v' ? 'video/webm' : 'image/jpeg') });
      if(isIOS && navigator.canShare && navigator.canShare({ files:[file] })){
        await navigator.share({ files:[file] });                       // Save Image / Save Video
        return true;
      }
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = fname; a.style.display = 'none';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(()=> URL.revokeObjectURL(url), 30000);
      if(!quiet) toast('✅ Phone me save ho gaya (Gallery → Download album)');
      return true;
    }catch(err){
      if(err && err.name === 'AbortError') return false;               // user ne share sheet band ki
      console.error('gallery save', err); toast('Save nahi ho paya.'); return false;
    }
  }
  window.cxGallerySave = save;
  window.cxAutoSave = function(file){
    try{ if(localStorage.getItem('cxAutoGal') === '0') return; }catch(e){}
    if(isIOS) return;                                                  // iOS par share sheet auto nahi khul sakti
    save(file, file.name, /^video/.test(file.type) ? 'v' : 'i', true).then(ok=>{ if(ok) toast('📥 Camera ki file phone me save ho gayi'); });
  };

  // viewer ke ⬇ buttons (dono viewers) -> seedha gallery save
  document.addEventListener('click', (e)=>{
    const b = e.target.closest && e.target.closest('#cxvSave, #cxVsave'); if(!b) return;
    const v = b.closest('#cxvOv, #cxView'); if(!v || !v.dataset.src) return;
    e.stopImmediatePropagation(); e.preventDefault();
    const isVid = !!v.querySelector('video');
    save(v.dataset.src, v.dataset.name, isVid ? 'v' : 'i');
  }, true);

  // chat bubbles: photo/video ke neeche "⬇ Gallery"
  const css = document.createElement('style');
  css.textContent = '.cxDl{display:inline-flex;align-items:center;gap:6px;margin:6px 0 0;padding:7px 13px;border-radius:16px;border:1px solid #3a3d47;background:#23252d;color:#cfd0d4;font-size:14px;font-family:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}.cxDl:active{background:#3a3550}.cxDl[disabled]{opacity:.6}';
  document.head.appendChild(css);
  async function onDl(e){
    e.preventDefault(); e.stopPropagation();
    const b = e.currentTarget; if(b.disabled) return; b.disabled = true; const t0 = b.textContent; b.textContent = '…';
    try{
      const d = await window.cxGetFile(b.dataset.fid);
      const blob = (typeof d === 'string') ? await (await fetch(d)).blob() : (d instanceof Blob ? d : null);
      if(!blob) throw new Error('no data');
      await save(blob, b.dataset.n, b.dataset.k);
    }catch(err){ console.error(err); toast('Ye file load nahi ho paayi.'); }
    b.disabled = false; b.textContent = t0;
  }
  function scan(){
    if(!window.cxGetFile) return;
    document.querySelectorAll('#chatMsgs img.cimg[data-fid]:not([data-dl]), #chatMsgs .cfile[data-act="vid"][data-fid]:not([data-dl])').forEach(el=>{
      el.setAttribute('data-dl', '1');
      const fid = el.dataset.fid; if(!fid) return;
      const isVid = el.classList.contains('cfile');
      const b = document.createElement('button'); b.type = 'button'; b.className = 'cxDl'; b.textContent = '⬇ Gallery';
      b.dataset.fid = fid; b.dataset.k = isVid ? 'v' : 'i'; b.dataset.n = isVid ? (el.dataset.n || 'video') : 'photo_' + Date.now() + '.jpg';
      b.addEventListener('click', onDl);
      el.insertAdjacentElement('afterend', b);
    });
  }
  setInterval(()=>{ try{ scan(); }catch(e){} }, 700);

  // camera khule to draw overlay band (warna camera ke upar overlay aa jata)
  const t = setInterval(()=>{
    if(typeof window.cxOpenCam !== 'function' || window.cxOpenCam.__hw) return;
    const orig = window.cxOpenCam;
    window.cxOpenCam = function(){ try{ HandWrite.close(); }catch(e){} return orig.apply(this, arguments); };
    window.cxOpenCam.__hw = true; clearInterval(t);
  }, 400);
})();


// ============================================================================
// CHAT PLUS 18: TEXT SIZE  A− / A+  (chat bubbles + type karne wala box)
//   - Chat khulte hi right side me chhota pill: [A−] [19] [A+]. Tap = 1px kam/zyada (12–30). Beech ka number = default (19) par wapas.
//   - Save: localStorage 'cxFs'. CSS var --cxfs (#chatOverlay par). Messages ke upar do ungli pinch bhi chalta hai.
// ============================================================================
(function chatTextSize(){
  const MIN = 12, MAX = 30, DEF = 19;
  let fs = DEF; try{ const v = Number(localStorage.getItem('cxFs')); if(v >= MIN && v <= MAX) fs = v; }catch(e){}
  const css = document.createElement('style');
  css.textContent = `
  #chatOverlay{--cxfs:${fs}}
  #chatOverlay #chatMsgs .cbub{font-size:calc(var(--cxfs,19) * 1px)!important;line-height:1.5!important}
  #chatOverlay .chatComposer #chatInput{font-size:max(16px, calc(var(--cxfs,19) * 1px - 1px))!important}
  #cxFsPill{position:fixed;right:8px;top:90px;z-index:2147482000;display:none;align-items:center;gap:2px;padding:3px;border-radius:20px;background:rgba(28,29,35,.92);border:1px solid #34363f;box-shadow:0 3px 12px rgba(0,0,0,.45);transition:opacity .4s;opacity:1}
  #cxFsPill.show{display:flex}
  #cxFsPill.dim{opacity:.38}
  #cxFsPill button{border:0;background:transparent;color:#cfd0d4;font-family:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent;padding:0}
  #cxFsPill .fsb{width:38px;height:34px;border-radius:17px;font-weight:700}
  #cxFsPill .fsb:active{background:#2b2e36}
  #cxFsPill #cxFsM{font-size:13px}#cxFsPill #cxFsP{font-size:19px}
  #cxFsPill #cxFsN{min-width:26px;height:34px;font-size:12px;color:#8b8d95}`;
  document.head.appendChild(css);

  let pill = null, dimT = 0;
  const poke = ()=>{ if(!pill) return; pill.classList.remove('dim'); clearTimeout(dimT); dimT = setTimeout(()=>{ if(pill) pill.classList.add('dim'); }, 2500); };
  function set(v, quiet){
    fs = Math.max(MIN, Math.min(MAX, Math.round(v)));
    const ov = document.getElementById('chatOverlay'); if(ov) ov.style.setProperty('--cxfs', fs);
    try{ localStorage.setItem('cxFs', String(fs)); }catch(e){}
    const n = document.getElementById('cxFsN'); if(n) n.textContent = fs;
    poke();
    try{ if(!quiet && typeof chatNearBottom === 'function' && chatNearBottom()) chatScrollBottom(); }catch(e){}
  }
  function build(){
    if(pill) return;
    pill = document.createElement('div'); pill.id = 'cxFsPill';
    pill.innerHTML = '<button type="button" class="fsb" id="cxFsM" aria-label="Text chhota">A−</button><button type="button" id="cxFsN" aria-label="Normal size">' + fs + '</button><button type="button" class="fsb" id="cxFsP" aria-label="Text bada">A+</button>';
    document.body.appendChild(pill);
    const tap = (id, fn)=>{ const b = pill.querySelector(id); b.addEventListener('pointerdown', (e)=>{ e.preventDefault(); }); b.addEventListener('click', (e)=>{ e.preventDefault(); fn(); }); };
    // dabaye rakho to lagataar badhta/ghatta hai
    const hold = (id, d)=>{ const b = pill.querySelector(id); let t = 0, iv = 0, held = false;
      b.addEventListener('pointerdown', ()=>{ held = false; t = setTimeout(()=>{ held = true; iv = setInterval(()=> set(fs + d, true), 90); }, 380); });
      const stop = ()=>{ clearTimeout(t); clearInterval(iv); };
      b.addEventListener('pointerup', stop); b.addEventListener('pointercancel', stop); b.addEventListener('pointerleave', stop);
      b.addEventListener('click', (e)=>{ e.preventDefault(); if(held){ held = false; return; } set(fs + d); }); };
    hold('#cxFsM', -1); hold('#cxFsP', 1);
    tap('#cxFsN', ()=> set(DEF));
  }
  // pinch (do ungli) se bhi size
  function bindPinch(){
    const box = document.getElementById('chatMsgs'); if(!box || box.dataset.fsPinch) return; box.dataset.fsPinch = '1';
    let d0 = 0, f0 = fs;
    const dist = (t)=> Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);
    box.addEventListener('touchstart', (e)=>{ if(e.touches.length === 2){ d0 = dist(e.touches); f0 = fs; } }, { passive: true });
    box.addEventListener('touchmove', (e)=>{ if(e.touches.length === 2 && d0){ set(f0 * dist(e.touches) / d0, true); } }, { passive: true });
    box.addEventListener('touchend', ()=>{ d0 = 0; }, { passive: true });
  }
  function tick(){
    const conv = document.getElementById('chatConv');
    const open = !!(conv && !conv.hidden && conv.getClientRects().length);
    if(open){
      build(); bindPinch();
      const h = conv.querySelector('.chatHead'); const r = h && h.getBoundingClientRect();
      pill.style.top = ((r ? r.bottom : 70) + 8) + 'px';
      if(!pill.classList.contains('show')){ pill.classList.add('show'); const ov = document.getElementById('chatOverlay'); if(ov) ov.style.setProperty('--cxfs', fs); poke(); }
    }else if(pill){ pill.classList.remove('show'); }
  }
  setInterval(()=>{ try{ tick(); }catch(e){} }, 400);
})();
